import { EventRegistry } from "../../../utils/event-registry";

export class EventService {
  constructor(component, services) {
    this.component = component;
    this.domService = services.domService;
    this.stateService = services.stateService;
    this.formService = services.formService;
    // for managing event listeners
    this.eventRegistry = new EventRegistry();

    // bind methods to maintain 'this' context
    this.handleKeyDown = this.handleKeyDown.bind(this);
    this.handleDropdownToggle = this.handleDropdownToggle.bind(this);
    this.handleDropdownContainerFocusOut = this.handleDropdownContainerFocusOut.bind(this);
    this.handleInputClear = this.handleInputClear.bind(this);
    this.handleSearchInput = this.handleSearchInput.bind(this);
    this.toggleDropdownOpen = this.toggleDropdown.bind(this, true);
    this.handleInputBlur = this.onInputBlur.bind(this);
    this.setDontCloseDropdownTrue = this.setDontCloseDropdown.bind(this, true);
    this.setDontCloseDropdownFalse = this.setDontCloseDropdown.bind(this, false);
    this.preventDropdownOpen100ms = this.preventDropdownOpen.bind(this, 100);
    this.setIsComposingTrue = this.setIsComposing.bind(this, true);
    this.handleCompositionEndBound = this.handleCompositionEnd.bind(this);

    // flags for event control
    this.dontCloseDropdown = false;
    this.dontOpenDropdown = false;
    this.dontOpenDropdownTimeoutId = null;
  }

  addEventListener(element, eventName, callback, options = {}) {
    this.eventRegistry.addEventListener(element, eventName, callback, options);
  }

  removeEventListener(element, eventName, callback, options = {}) {
    this.eventRegistry.removeEventListener(element, eventName, callback, options);
  }

  setupEventListeners() {
    // add event listeners to the component
    this.addEventListener(this.component.shadowRoot, 'keydown', this.handleKeyDown);

    // set up dropdown toggle events
    this.setupDropdownToggleEvents();

    // set up input events
    this.setupInputEvents();

    // set up search input events if searchable
    this.setupSearchEvents();

    // set up position update listeners
    this.domService.setupPositionListeners();

    // set up dropdown item listeners
    this.setupDropdownItemListeners();
  }

  removeEventListeners() {
    this.eventRegistry.removeAllEventListeners();

    // clear any pending timeouts
    clearTimeout(this.dontOpenDropdownTimeoutId);
  }

  setupDropdownToggleEvents() {
    const cInput = this.component.shadowRoot.querySelector('.c-input');
    const isMultiple = this.stateService.isMultiple();

    // common events
    this.addEventListener(cInput, 'click', this.handleDropdownToggle);

    this.addEventListener(this.component, 'focusin', this.toggleDropdownOpen);

    const dropdownContainer = this.domService.getDropdownContainer();
    this.addEventListener(dropdownContainer, 'focusout', this.handleDropdownContainerFocusOut);

    this.addEventListener(this.component, 'blur', this.handleInputBlur);

    const optionsContainer = document.querySelector(`#${this.component.dropdownId} ul.options`);
    if (optionsContainer) {
      // prevent dropdown from closing when option in multiple select is clicked
      this.addEventListener(optionsContainer, 'mousedown', this.setDontCloseDropdownTrue);

      this.addEventListener(optionsContainer, 'mouseleave', this.setDontCloseDropdownFalse);
      this.addEventListener(optionsContainer, 'mouseup', this.setDontCloseDropdownFalse);
    }

    if (isMultiple) {
      // multiple select specific events
      const clearIcon = this.component.shadowRoot.querySelector('.c-input__r-icon');
      if (clearIcon) {
        // prevent dropdown from opening when clear icon is clicked
        this.addEventListener(clearIcon, 'mousedown', this.preventDropdownOpen100ms);
        this.addEventListener(clearIcon, 'mouseup', this.preventDropdownOpen100ms);
        this.addEventListener(clearIcon, 'mouseleave', this.preventDropdownOpen100ms);
      }
    }
  }

  setupInputEvents() {
    const input = this.component.shadowRoot.querySelector('.c-input__input');

    // listen for clear button click
    this.addEventListener(input, 'c-input__input-cleared', this.handleInputClear);
  }

  setupSearchEvents() {
    if (!this.stateService.isSearchable()) return;

    const searchInput = document.querySelector(`#${this.component.dropdownId} .search input`);
    if (!searchInput) return;

    // handle search input
    this.addEventListener(searchInput, 'input', this.handleSearchInput);
    this.addEventListener(searchInput, 'keydown', this.handleKeyDown);

    // handle ime composition (for languages like chinese, japanese)
    this.addEventListener(searchInput, 'compositionstart', this.setIsComposingTrue);

    this.addEventListener(searchInput, 'compositionend', this.handleCompositionEndBound);
  }

  setupDropdownItemListeners() {
    const dropdownItems = this.domService.getDropdownItems();

    dropdownItems.forEach(item => {
      this.addEventListener(item, 'click', this.handleOptionChange.bind(this, item, false));
    });
  }

  onInputBlur() {
    if (this.stateService.isSearchable() || this.dontCloseDropdown) return;

    const recentValue = this.stateService.getRecentValue();
    const value = this.stateService.getValue();
    if (recentValue && recentValue !== value) {
      const selectItem = this.domService.getSelectedItem();
      this.handleOptionChange(selectItem);
    } else {
      // 防止重複 toggleDropdown 沒有跑變更選項邏輯 直接隱藏選單
      this.toggleDropdown(false);
    }
  }

  setDontCloseDropdown(value) {
    this.dontCloseDropdown = value;
  }

  setIsComposing(value) {
    this.stateService.setIsComposing(value);
  }

  handleCompositionEnd() {
    const searchInput = document.querySelector(`#${this.component.dropdownId} .search input`);
    if (!searchInput) return;

    this.stateService.setIsComposing(false);
    searchInput.dispatchEvent(new Event('input'));
  }

  /**
   * 按下Enter或滑鼠點擊選單選項，執行變更選項相關邏輯
   */
  handleOptionChange(option, arrowKeyChange = false) {

    if (!option) return;

    const dropdownIsOpen = this.stateService.isDropdownOpen();
    const searchInput = this.domService.getSearchInput();
    const input = this.component.shadowRoot.querySelector('.c-input__input');
    const isMultiple = this.stateService.isMultiple();
    const singleSelect = !this.stateService.isMultiple();
    const isSearching = this.stateService.isSearching();
    const isSearchable = this.stateService.isSearchable();

    // 鍵盤上下箭頭更換選項且不是多選的處理
    if (arrowKeyChange && singleSelect) {
      // 如果下拉選單是關閉應該要觸發 changeEvent
      this.selectItem(input, option, false, true, !dropdownIsOpen, true);
    } else {
      this.selectItem(input, option, isMultiple);
    }

    if (searchInput.value) {
      // prevent dropdown container open in the opposite direction
      this.stateService.setIsSearching(true)
    }

    this.domService.updateDropdownPosition();
    this.stateService.setIsSearching(false);
    this.domService.updateDropdownWidth();

    if (isSearchable) {
      this.dontCloseDropdown = true;
      searchInput.focus();
      this.dontCloseDropdown = false;
    }

    // input重新獲得焦點會清空搜尋結果
    // 不是用鍵盤上下箭頭變更選項且搜尋列無值
    // 才重新獲取焦點 c-select 顯示input(不然上下鍵會觸發 focusout導致跑版)
    const noMultipleSearchSelect = !(isMultiple && isSearchable);
    if (!arrowKeyChange && noMultipleSearchSelect && !searchInput.value && input) {
      input.focus();
    }

    if (singleSelect && !arrowKeyChange) {
      // 單選且不是鍵盤上下鍵才判斷下拉選單顯示隱藏
      this.toggleDropdown(!dropdownIsOpen);
    }

    // 單選的c-select 下面兩個情況要同步資料，不然會誤判要不要變更select值的時機
    // 1. 用滑鼠左鍵點選選項
    // 2. 焦點在c-select上且選項列表屬隱藏狀態
    if (singleSelect && (arrowKeyChange != dropdownIsOpen)) {
      this.stateService.syncRecentValue();
    }

    const arrowSelectItem = this.domService.getArrowSelectItem();
    const arrowSelectItemVal = arrowSelectItem && arrowSelectItem.value;
    // 先移除上個標記 keydownSelect 的元素
    if (arrowSelectItemVal && arrowSelectItemVal !== option.value) {
       arrowSelectItem.removeAttribute('arrow-select');
      // 對當前元素添加 arrow-select 屬性
      if (!option.hasAttribute('arrow-select')) {
          option.toggleAttribute('arrow-select');
      }
    }

  }

  setupTagCloseListeners(closeIcon, value) {
    this.addEventListener(closeIcon, 'mousedown', this.tagCloseIconClick.bind(this, value));
  }

  handleDropdownToggle() {
    if (this.stateService.isDisabled() || this.stateService.isReadonly()) return;
    this.toggleDropdown(true);
  }

  handleDropdownContainerFocusOut() {
    if (this.dontCloseDropdown) return;

    this.toggleDropdown(false);
  }

  handleInputClear() {
    this.clearAllSelectedItems();
  }

  handleSearchInput(e) {
    // 按上下箭頭忽略搜尋輸入邏輯
    const isArrowKeyDown = e.key == 'ArrowUp' || e.key == 'ArrowDown';
    if (this.stateService.isComposing() || isArrowKeyDown) return;

    const keyword = e.target.value.trim().toLowerCase();
    const dropdownItems = this.domService.getDropdownItems();

    dropdownItems.forEach(item => {
      const text = item.textContent.trim().toLowerCase();
      item.style.display = keyword === '' || text.includes(keyword) ? 'flex' : 'none';
    });

    this.stateService.setIsSearching(true);
    this.domService.updateDropdownPosition();
    this.stateService.setIsSearching(false);
  }

  tagCloseIconClick(value, e) {
    if (this.component.stateService.isDisabled() || this.stateService.isReadonly()) return;
    this.component.stateService.removeValue(value);
    this.domService.updateSelectedItems();
    this.component.dispatchEvent(new Event('change'));

    e.stopPropagation();
    this.dontCloseDropdown = false;
  }

  handleKeyDown(e) {
    if (this.stateService.isDisabled() || this.stateService.isReadonly()) return;

    switch (e.key) {
      case 'ArrowDown':
      case 'ArrowUp':
        this.handleArrowKeys(e);
        break;
      case 'Enter':
        this.handleEnterKey();
        break;
      case 'Escape':
        this.toggleDropdown(false);
        break;
    }
  }

  handleArrowKeys(e) {
    e.preventDefault();
    const isMultiple = this.stateService.isMultiple();
    const dropdownItems = this.domService.getDropdownItems();
    const visibleItems = [...dropdownItems].filter(item => item.style.display !== 'none');
    if (visibleItems.length === 0) return;

    let selectItem;
    if (isMultiple) {
      selectItem = this.domService.getArrowSelectItem();
    } else {
      selectItem = this.domService.getSelectedItem();
    }

    const visibleIndex = selectItem ? visibleItems.indexOf(selectItem) : -1;
    let nextItemIndex = -1;
    if (e.key === 'ArrowDown') {
      if (visibleIndex < visibleItems.length - 1) {
        nextItemIndex = visibleIndex + 1;
      } else {
        nextItemIndex = 0; // wrap around to the first item
      }
    } else { // arrowup
      if (visibleIndex > 0) {
        nextItemIndex = visibleIndex - 1;
      } else {
        nextItemIndex = visibleItems.length - 1; // wrap around to the last item
      }
    }

    let nextItem = visibleItems[nextItemIndex];
    // 可能找到不存在的資料直接 return 不往後做
    if (!nextItem) {
      return;
    }

    // 多選只註記 keydown-select屬性，代表按Enter新增的選項
    // 並且只有按Enter或滑鼠點選項才改變選擇值
    // keyDown 只跳過顯示值
    if (isMultiple) {
       // 先移除上個標記 keydownSelect 的元素
       if (selectItem) {
          selectItem.removeAttribute('arrow-select');
       }

       // 對當前元素添加 keydownSelect 屬性
      nextItem.toggleAttribute('arrow-select');

    } else {
        // 已經呈現搜尋結果，還沒選擇資料不往後處理
        const searchInput = this.domService.getSearchInput();
        if (searchInput.value && !nextItem) {
          return;
        }

        // 單選直接跑變更選項邏輯
        this.handleOptionChange(nextItem, true);
    }

    // 控制container scroll 到當前選項位置
    nextItem.scrollIntoView({block: "center"});
  }

  handleEnterKey() {
    let selectOption;
    if (this.stateService.isMultiple()) {
      selectOption = this.domService.getArrowSelectItem();
    } else {
      selectOption = this.domService.getSelectedItem();
    }

    this.handleOptionChange(selectOption);
  }

  /**
   * 顯示或隱藏選單
   */
  toggleDropdown(open = true) {

    if (this.stateService.isDisabled() || this.stateService.isReadonly()) return;

    if (open === false && this.dontCloseDropdown) return;
    if (open && this.dontOpenDropdown) return;

    const dropdownIsOpen = this.stateService.isDropdownOpen();

    // update dropdown position and width
    if (open) {
      this.domService.updateDropdownWidth();
      this.domService.updateDropdownPosition();

      if (!this.stateService.isMultiple()) {
        this.stateService.syncRecentValue();
        const anchorEle = this.domService.getSelectedItem();
        if(anchorEle) {
           anchorEle.scrollIntoView({block: "center"});
        }
      }
    }

    if (!open) {
       if (this.stateService.isMultiple()) {
          // 移動scrollBar到當前選項位置
          const dropDownItems = this.domService.getDropdownItems();
         if (dropDownItems && dropDownItems[0] && dropdownIsOpen) {
            dropDownItems[0].scrollIntoView({block: "center"});
         }
       }

       const arrowSelectItem = this.domService.getArrowSelectItem();
       if (arrowSelectItem) {
         arrowSelectItem.removeAttribute('arrow-select');
       }
    }

    // update state
    this.stateService.setDropdownOpen(open);

  }

  preventDropdownOpen(ms) {
    this.dontOpenDropdown = true;

    clearTimeout(this.dontOpenDropdownTimeoutId);
    this.dontOpenDropdownTimeoutId = setTimeout(() => {
      this.dontOpenDropdown = false;
    }, ms);
  }

  selectItem(input, item, isMultiple = false, forceSelect = false, triggerChangeEvent = true, keepDropdownOpen = false) {
    if (!item) {
      this.clearAllSelectedItems();

      if (triggerChangeEvent) {
        this.component.dispatchEvent(new Event('change'));
      }

      return;
    }

    const value = item.getAttribute('value');
    const label = item.textContent.trim();
    const dropdownItems = this.domService.getDropdownItems();
    const recentValue = this.component.recentValue;

    // 當選單為隱藏狀態 單選select 會觸發 changeEvent
    // 同時檢查 當前值跟上次選擇的選項是否相同
    // 如果一樣不改變 value
    if (triggerChangeEvent && recentValue === value) {
      return;
    }

    if (isMultiple) {
      // multiple select behavior
      const currentValues = this.stateService.getValues();
      const valueExists = currentValues.includes(value);

      if (valueExists && !forceSelect) {
        // remove value if already selected
        item.classList.remove('selected');
        this.stateService.removeValue(value);
      } else {
        // add value
        item.classList.add('selected');
        this.stateService.addLabelAndValue(label, value);
      }

      // update ui
      this.domService.updateMultiSelectTags();
    } else {
      // single select behavior
      input.value = label;
      this.formService.setFormValue(value);

      this.stateService.setValue(value);

      // update selected state in dropdown
      dropdownItems.forEach(item => item.classList.remove('selected'));
      item.classList.add('selected');
      this.stateService.setSelectedIndex([...dropdownItems].indexOf(item));

      if (!keepDropdownOpen) {
        this.toggleDropdown(false);
      }
    }

    // dispatch change event if requested
    if (triggerChangeEvent) {
      this.component.dispatchEvent(new Event('change'));
    }
  }

  clearAllSelectedItems() {
    const input = this.component.shadowRoot.querySelector('.c-input__input');
    const dropdownItems = this.domService.getDropdownItems();

    // clear selection in dropdownitems
    dropdownItems.forEach(item => {
      item.classList.remove('selected');
    });

    // clear input value
    input.value = '';

    // clear state
    const oriValues = this.stateService.getValues();
    if (this.stateService.isMultiple()) {
      this.stateService.clearValues();
      this.domService.updateMultiSelectTags();
    } else {
      this.formService.setFormValue(null);
      this.stateService.setValue('');
      this.stateService.setSelectedIndex(-1);
      this.stateService.syncRecentValue();
    }

    // close dropdown
    this.toggleDropdown(false);

    // dispatch change event
    if (this.stateService.isMultiple() && oriValues.length > 0) {
      this.component.dispatchEvent(new Event('change'));
    }
  }
}
