import '../components/tippy/tippy';
import './_ctbc-form';
import {appendAsterisk, appendPendingText} from "./_ctbc-form";

document.addEventListener('DOMContentLoaded', () => {
  // 如果 .form-card.all-fields 裡的 label有 .required，則在 label 後面加上 *
  // 如果 .form-card.all-fields 裡的 label有 .pending-approval，則在 label 後面加上 (待放行)
  document.querySelectorAll(".form-card.all-fields label").forEach(label => {
    if (label.classList.contains('required') && !label.querySelector('.asterisk')) {
      appendAsterisk(label);
    }
    if (label.classList.contains('pending-approval') && !label.querySelector('.pending-approval-text')) {
      appendPendingText(label);
    }
  });
  // 如果 th 有 .required，則在 th 後面加上 *
  document.querySelectorAll("th.required").forEach(th => {
    if (!th.querySelector('.asterisk')) {
      appendAsterisk(th);
    }
  });

  // 使用 MutationObserver 監控 DOM 變化，動態更新 label
  const observer = new MutationObserver((mutations, observer) => {
    for (const mutation of mutations) {
      if (mutation.type === 'childList') {
        // monitor newly added nodes
        mutation.addedNodes.forEach(node => {
          if (node.nodeType === Node.ELEMENT_NODE) { // <div>, <p>, etc.
            const labels = node.querySelectorAll('.form-card.all-fields label');
            labels.forEach(label => {
              if (label.classList.contains('required') && !label.querySelector('.asterisk')) {
                appendAsterisk(label);
              }
              if (label.classList.contains('pending-approval') && !label.querySelector('.pending-approval-text')) {
                appendPendingText(label);
              }
            });
          }
        });
      }

      // monitor class changes in existing nodes
      if (mutation.type === 'attributes' && mutation.attributeName === 'class') {
        const target = mutation.target;
        if (target.matches('.form-card.all-fields label')) {
          // handle adding/removing required asterisk
          if (target.classList.contains('required') && !target.querySelector('.asterisk')) {
            appendAsterisk(target);
          } else if (!target.classList.contains('required')) {
            const asterisk = target.querySelector('.asterisk');
            if (asterisk) asterisk.remove();
          }

          // handle adding/removing pending approval text
          if (target.classList.contains('pending-approval') && !target.querySelector('.pending-approval-text')) {
            appendPendingText(target);
          } else if (!target.classList.contains('pending-approval')) {
            const pendingText = target.querySelector('.pending-approval-text');
            if (pendingText) pendingText.remove();
          }
        }
      }
    }
  });
  observer.observe(document.body, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ['class']
  });


  /**
   * ctrl + / to focus on search input
   */
  let ctrlSlashEventListenerAdded = false;
  if (!ctrlSlashEventListenerAdded) {
    ctrlSlashEventListenerAdded = true;
    document.addEventListener('keydown', e => {
      if (e.ctrlKey && e.key === '/') {
        const hamburger = top.document.querySelector('.hamburger');
        if (hamburger?.classList.contains('collapse')) {
          top.toggleMenu();
        }
        top.focusSearch();
      }
    });
  }

  /**
   * alt + q to show/hide current url
   */
  let altQEventListenerAdded = false;
  if (!altQEventListenerAdded) {
    altQEventListenerAdded = true;
    document.addEventListener('keydown', e => {
      if (e.altKey && e.key.toLowerCase() === 'q') {
        // add top right corner url display box
        let urlDisplayBox = document.getElementById('url-display-box');
        if (urlDisplayBox) {
          urlDisplayBox?.remove();
          document.body.style.border = '';
          return;
        }
        if (!urlDisplayBox) {
          urlDisplayBox = document.createElement('div');
          urlDisplayBox.id = 'url-display-box';
          urlDisplayBox.style.position = 'fixed';
          urlDisplayBox.style.bottom = '3px';
          // urlDisplayBox.style.left = '20px';
          urlDisplayBox.style.backgroundColor = 'rgba(0, 0, 0, 0.6)';
          urlDisplayBox.style.color = 'white';
          urlDisplayBox.style.padding = '5px';
          urlDisplayBox.style.paddingRight = '30px';
          urlDisplayBox.style.borderRadius = '5px';
          urlDisplayBox.style.zIndex = '10000';
          urlDisplayBox.style.fontSize = '12px';
          urlDisplayBox.style.wordWrap = 'break-word';
          urlDisplayBox.textContent = `${window.location.href}`;

          // close button
          const closeButton = document.createElement('span');
          closeButton.textContent = '×';
          closeButton.style.position = 'absolute';
          closeButton.style.top = '3px';
          closeButton.style.right = '5px';
          closeButton.style.cursor = 'pointer';
          closeButton.style.fontSize = '13px';
          closeButton.style.fontWeight = 'bold';
          closeButton.addEventListener('click', () => {
            urlDisplayBox?.remove();
            document.body.style.border = '';
          });
          urlDisplayBox.appendChild(closeButton);
          document.body.appendChild(urlDisplayBox);

          // add red border to current document body to indicate url display box is active
          document.body.style.border = '3px solid rgba(255, 0, 0, 0.6)';
        }
      }
    });
  }
});
