import htmlStr from './CsfdsTabs.html';
import cssStr from './CsfdsTabs.scss';
import {appendCssToHead} from "../../utils/web-comp-utils";
import {isChildOf, waitMs, generateUUID} from "../../utils/utils";

/**
 * Events:
 *  c-tab-change: when the tab is changed
 */
export default class CsfdsTabs extends HTMLElement {
  #componentUuid = generateUUID();
  // 當前focus的tab index
  #currentTabIdx = 0;
  // 隱藏中的tab indexes
  #hiddenTabIdxs = [];

  static define() {
    customElements.define('c-tabs', CsfdsTabs);
  }

  constructor() {
    super();
    if (!this.hasRendered) {
      this.style.display = 'none';
    }
  }

  get hasRendered() {
    return this.getAttribute('rendered');
  }

  set hasRendered(val) {
    this.setAttribute('rendered', val);
  }

  get isNestedChild() {
    return this.parentElement?.closest('c-tabs') !== null;
  }

  get ele() {
    return {
      tabBtns: this.querySelectorAll(':scope>.c-tabs>button.tab'),
      tabPanes: this.querySelectorAll(':scope>.c-tab-panes>.pane')
    };
  }

  async connectedCallback() {
    // 如果是nested c-tabs, 看下自己是不是已經被放到.c-tab-panes .pane裡面
    // 如果不是，代表還沒輪到自己render
    if (this.isNestedChild) {
      const parentCTabs = this.parentElement?.closest('c-tabs');
      const parentCTabPane = this.parentElement?.closest('.pane');
      if (!isChildOf(parentCTabPane, parentCTabs)) {
        return;
      }
    }

    // 如果是nested c-tabs, wait until parent c-tabs is rendered
    const hasParentRendered = await this.#directParentCTabsIsRendered();
    if (!hasParentRendered) {
      return;
    }

    if (!this.hasRendered) {
      this.innerHTML = this.#constructHtml(htmlStr);
      appendCssToHead(cssStr, 'csfds-tabs-style');

      // bind event listeners
      const cTabsBtns = this.querySelectorAll(':scope>.c-tabs>button.tab');
      cTabsBtns.forEach(tabBtn => {
        tabBtn.addEventListener('click', () => this.#openTabByBtn(tabBtn));
      });

      // open the first tab by default
      this.style.display = 'block';
      if (cTabsBtns.length > 0) {
        this.#openTabByBtn(cTabsBtns[0]);
      }

      this.hasRendered = true;
    }
  }

  /**
   * @param {number} tabIdx
   */
  openTab(tabIdx) {
    const tabBtns = this.ele.tabBtns;
    if (tabIdx < 0 || tabIdx >= tabBtns.length) {
      console.error(`[#${this.getAttribute('id')}] Invalid tab index: ${tabIdx}`);
      return;
    }

    this.#openTabByBtn(tabBtns[tabIdx]);
  }

  /**
   * @param {HTMLElement} tabBtn
   */
  #openTabByBtn(tabBtn) {
    // move underline
    this.#moveUnderline(tabBtn);

    // tab btn add active style
    const tabBtns = this.ele.tabBtns;
    tabBtns.forEach(tab => tab.classList.remove('active'));
    tabBtn.classList.add('active');

    // hide all panes, then show the selected one
    const tabPanes = this.ele.tabPanes;
    tabPanes.forEach(pane => {
      pane.classList.remove('active');
    });
    // setTimeout to wait for the fading animation to finish
    setTimeout(() => {
      tabPanes.forEach(pane => {
        pane.classList.add('d-none');
      });
      const activePane = this.querySelector(`#${tabBtn.getAttribute('data-target')}`);
      activePane.classList.remove('d-none');
      activePane.classList.add('active');


      // update current tab index and dispatch event if changed
      const oriTabIdx = this.#currentTabIdx;
      const currTabIdx = [...tabBtns].indexOf(tabBtn);
      if (oriTabIdx === currTabIdx) {
        return; // same tab, no need to update
      }

      this.#currentTabIdx = currTabIdx;

      // dispatch c-tab-change event
      this.dispatchEvent(new CustomEvent('c-tab-change', {
        detail: {
          currentTabIdx: this.#currentTabIdx,
          currentTabPane: this.ele.tabPanes[this.#currentTabIdx]
        },
        bubbles: true,
        composed: true
      }));
    }, 150);
  }

  /**
   * @param {number} tabIdx
   */
  hideTab(tabIdx) {
    const tabBtns = this.ele.tabBtns;
    if (tabIdx < 0 || tabIdx >= tabBtns.length) {
      console.error(`[#${this.getAttribute('id')}] Invalid tab index: ${tabIdx}`);
      return;
    }

    if (this.#hiddenTabIdxs.includes(tabIdx)) {
      // already hidden
      return;
    }

    // hide tab button and pane
    const tabBtn = tabBtns[tabIdx];
    const tabPane = this.ele.tabPanes[tabIdx];
    this.#hiddenTabIdxs.push(tabIdx);
    tabBtn.style.display = 'none';
    tabPane.style.display = 'none';

    // move underline to the previous tab
    // 如果全都隱藏了, 就也藏起來底線
    if (this.#hiddenTabIdxs.length === tabBtns.length) {
      this.#hideUnderline();
      this.#currentTabIdx = -1;
      return;
    }
    // 如果focus tab左邊的tab被隱藏，underline刷新下
    if (this.#currentTabIdx > tabIdx) {
      this.#moveUnderline(tabBtns[this.#currentTabIdx]);
    } else if (this.#currentTabIdx < tabIdx) {
      // 如果focus tab右邊的tab被隱藏，好像也不用做什麼事
    } else {
      // 如果focus tab被隱藏，找下一個要顯示的tab
      const nextTabIdx = this.#getToBeFocusTabIdx(this.#hiddenTabIdxs, this.#currentTabIdx, tabIdx, tabBtns.length);
      if (nextTabIdx >= 0) {
        this.#openTabByBtn(tabBtns[nextTabIdx]);
      }
    }
  }

  /**
   * @param tabIdx
   */
  unhideTab(tabIdx) {
    const tabBtns = this.querySelectorAll(`:scope>.c-tabs>button.tab`);
    if (tabIdx < 0 || tabIdx >= tabBtns.length) {
      console.error(`[#${this.getAttribute('id')}] Invalid tab index: ${tabIdx}`);
      return;
    }

    if (!this.#hiddenTabIdxs.includes(tabIdx)) {
      // already shown
      return;
    }

    // unhide tab button and pane
    const tabBtn = tabBtns[tabIdx];
    const tabPane = this.ele.tabPanes[tabIdx];
    this.#hiddenTabIdxs = this.#hiddenTabIdxs.filter(idx => idx !== tabIdx);
    tabBtn.style.removeProperty('display');
    tabPane.style.removeProperty('display');

    // move underline to the previous tab
    // if all tabs are hidden, show this tab
    if (this.#currentTabIdx == -1) {
      this.#openTabByBtn(tabBtn);
    } else if (this.#currentTabIdx < tabIdx) {
      // 如果focus tab右邊的tab要被顯示；就顯示，不用更新underline
    } else {
      // 如果focus tab左邊的tab要被顯示，更新underline
      this.#moveUnderline(tabBtns[this.#currentTabIdx]);
    }
  }

  /**
   * 將底線移到指定的tabBtn下
   * @param {HTMLElement} tabBtn
   */
  #moveUnderline(tabBtn) {
    const underlineEle = this.querySelector(':scope>.c-tabs>.underline');
    underlineEle.classList.remove('opacity-0');
    underlineEle.style.left = (tabBtn.offsetLeft) + 'px';
    underlineEle.style.width = (tabBtn.clientWidth - 9.6) + 'px'; // 9.6px = 0.6rem
  }

  #hideUnderline() {
    const underlineEle = this.querySelector(':scope>.c-tabs>.underline');
    underlineEle.classList.add('opacity-0');
  }

  /**
   * 當當前tab被隱藏時，找出下個要顯示的tab index
   */
  #getToBeFocusTabIdx(hiddenTabIdxs, currenTabIdx, hideTabIdx, totalTabsLength) {
    if (currenTabIdx !== hideTabIdx) {
      // 如國當前tab index不是要被隱藏的tab，那也不用切換顯示新的tab
      return -1;
    }

    if (hiddenTabIdxs.length === totalTabsLength) {
      return -1;
    }

    if (currenTabIdx === hideTabIdx) {
      for (let i = currenTabIdx - 1; i >= 0; i--) {
        if (!hiddenTabIdxs.includes(i)) {
          return i;
        }
      }

      // 如果前面都沒有, 就找後面的
      for (let i = currenTabIdx + 1; i < totalTabsLength; i++) {
        if (!hiddenTabIdxs.includes(i)) {
          return i;
        }
      }
    }

    return -1;
  }

  #constructHtml(htmlTemplateStr) {
    let template = document.createElement('template');
    template.innerHTML = htmlTemplateStr;

    // get <c-tab> elements
    const tabs = this.querySelectorAll(':scope>c-tab');

    // create .c-tabs buttons
    tabs.forEach((tab, index) => {
      let tabButton = document.createElement('button');
      tabButton.setAttribute('type', 'button');
      tabButton.setAttribute('class', 'tab');
      tabButton.setAttribute('data-target', `tab-${this.#componentUuid}-${index}`);
      tabButton.innerHTML = tab.title;
      const cTabsDiv = template.content.querySelector('.c-tabs');
      // button should be before the <div class="underline opacity-0">
      cTabsDiv.insertBefore(tabButton, cTabsDiv.lastChild);
    });

    // create .c-tabs-panes panes
    tabs.forEach((tab, index) => {
      let tabPane = document.createElement('div');
      tabPane.setAttribute('class', 'pane');
      tabPane.setAttribute('id', `tab-${this.#componentUuid}-${index}`);
      if (tab.maxHeight) {
        tabPane.style.maxHeight = tab.maxHeight;
      }
      tabPane.innerHTML = tab.innerHTML;

      template.content.querySelector('.c-tab-panes').appendChild(tabPane);
    });

    // remove <c-tab> elements
    tabs.forEach(tab => tab.remove());

    return template.innerHTML;
  }

  /**
   * 如果有nested c-tab, 由外而內, 要先等外面的render完再換裡面的
   */
  async #directParentCTabsIsRendered() {
    const parentCTabs = this.parentElement?.closest('c-tabs');
    if (!parentCTabs) {
      return true;
    }

    let retryCountDown = 5;
    while (!parentCTabs.hasRendered) {
      retryCountDown--;

      if (retryCountDown === 0) {
        return false;
      }

      await waitMs(100);
    }

    return true;
  }
}
