import CsfdsHTMLElement from '../CsfdsHTMLElement';
import baseHtml from './CsfdsInput.html';
import baseCss from './CsfdsInput.scss';
import chkBoxHtml from './CheckBoxInput.html';
import chkBoxCss from './CheckBoxInput.scss';
import radioHtml from './RadioInput.html';
import radioCss from './RadioInput.scss';
import DateInputService from './DateInputService';
import CheckBoxRadioButtonService from "./CheckBoxRadioButtonService";

export default class CsfdsInput extends CsfdsHTMLElement {
  static define() {
    customElements.define('c-input', CsfdsInput);
  }

  static observedAttributes = [
    "class", "type", "placeholder", "value", "disabled", 
    "readonly", "autocomplete", "size", "maxlength", "checked"];

  // tells the browser to treat the element like a form control.
  static formAssociated = true;

  constructor() {
    super();
    this.rendered = false;
    this.checkBoxRadioService = new CheckBoxRadioButtonService(this);

    // Get access to the internal form control APIs
    this.internals_ = this.attachInternals();

    // base html and css
    this.html = baseHtml;
    this.css = baseCss;

    this.isTextInput = this.getAttribute('type') === 'text';

    // checkbox
    this.isCheckbox = this.getAttribute('type') === 'checkbox';
    this.isInitialChecked = false;
    if (this.isCheckbox) {
      this.isInitialChecked = this.getAttribute('checked') !== null;

      this.html = chkBoxHtml;
      this.css = chkBoxCss;
    }

    // radio
    this.isRadio = this.getAttribute('type') === 'radio';
    if (this.isRadio) {
      this.isInitialChecked = this.getAttribute('checked') !== null;

      this.html = radioHtml;
      this.css = radioCss;
    }

    // date input
    const inputType = this.getAttribute('type');
    this.isDateInput = inputType === 'date' || inputType === 'datetime-local' || inputType === 'month' || inputType === 'year';
    // date + time
    this.isDatetimePicker = inputType === 'datetime-local';
    // month
    this.isMonthPicker = inputType === 'month';
    // year
    this.isYearPicker = inputType === 'year';
    // has datetime format
    this.dateFormat = this.#getDateFormat();

    // c-select
    this.isSelect = false;

    // tracking value (when focus, blur)
    this.valueBeforeChange = null;
    this.valueAfterChange = null;
  }

  // mounted
  connectedCallback() {
    super.connectedCallback(this.html.trim(), this.css);
    this.#render();
    this.rendered = true;
  }

  attributeChangedCallback(attributeName, oldValue, newValue) {
    if (this.shadowRoot) {
      // copy attributes from host to shadow root
      const input = this.shadowRoot.querySelector('.c-input__input');
      if (input && attributeName) {
        this.#copyAttributes(input, 'c-input__input', attributeName, newValue);
      }
    }
  }

  reset() {
    const input = this.shadowRoot.querySelector('.c-input__input');
    if (this.isCheckbox || this.isRadio) {
      this.checked = this.isInitialChecked;
    } else {
      input.value = this.getAttribute('value');
      input.dispatchEvent(new Event('input'));
    }
  }

  focus() {
    const input = this.shadowRoot.querySelector('.c-input__input');
    input.focus();
  }

  select() {
    const input = this.shadowRoot.querySelector('.c-input__input');
    input.select();
  }

  clearFormInternals() {
    this.internals_.setFormValue(null);
  }

  #render() {
    if (this.rendered) return;

    const input = this.shadowRoot.querySelector('.c-input__input');
    if (input) {
      // copy attributes from host to shadow root's input
      this.constructor.observedAttributes.forEach(attribute => {
        if (this.getAttribute(attribute) !== null) {
          input.setAttribute(attribute, this.getAttribute(attribute));
          // "size" default set to ori.size - 2
          if (attribute === 'size' && this.getAttribute(attribute) > 2) {
            input.setAttribute(attribute, this.getAttribute(attribute) - 2);
          }
        }
      });
      input.classList.add('c-input__input');

      const inputDivBoxs = {
        'checkbox': '.checkbox__box'
      }

      const boxClassAttributes = ["disabled", "checked"];
      for (let i = 0; i < boxClassAttributes.length; i++) {
        const checkAttr = boxClassAttributes[i];
        // 有套用屬性 才添加到class
        if (!input[checkAttr]) {
          continue;
        }

        const boxSelector = inputDivBoxs[input.type] || "";
        if (boxSelector && this.shadowRoot.querySelector(boxSelector)) {
          const inputDivBox = this.shadowRoot.querySelector(boxSelector);
          inputDivBox.classList.add(checkAttr);
        }
      }

      // bind input value to internals
      input.addEventListener('input', (e) => {
        if (this.isCheckbox && !input.checked) {
          this.internals_.setFormValue(null);
        } else {
          const sanitizedValue = this.#sanitizeValue(input.value);
          input.value = sanitizedValue;
          this.internals_.setFormValue(sanitizedValue);
        }
      });

      // set initial value
      if (this.isCheckbox || this.isRadio) {
        this.checked = this.isInitialChecked;
      } else {
        if (this.hasAttribute('value')) {
          this.internals_.setFormValue(this.getAttribute('value'));
        }
      }
    }

    // 模擬input 觸發onchange事件
    if (this.isTextInput) {
      input.addEventListener('focus', (e) => {
        this.valueBeforeChange = input.value;
      });

      input.addEventListener('blur', (e) => {
        this.valueAfterChange = input.value;
        if (this.valueBeforeChange !== this.valueAfterChange) {
          this.dispatchEvent(new Event('change'));
        }
      });
    }

    // clear button click event
    const clearButton = this.shadowRoot.querySelector('.c-input__r-icon.clear');
    if (clearButton) {
      clearButton.addEventListener('click', () => {
        if (this.hasAttribute('disabled') || this.hasAttribute('readonly')) { return; }
        this.#clearInput(input);
      });
    }

    // enter key press event
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !this.isSelect) {
        this.closest('form')?.requestSubmit();
      }
    });

    // date, datetime
    if (this.isDateInput) {
      input.setAttribute('type', 'text');
      const dateInputService = new DateInputService(
        this,
        input, 
        this.internals_,
        this.#clearInput.bind(this, input),
        this.isDatetimePicker,
        this.isMonthPicker,
        this.isYearPicker,
        this.dateFormat);

      input.addEventListener('c-input__input-cleared', (e) => {
        dateInputService.clearDatePicker();
      });
      
      input.addEventListener('change', (e) => {
        dateInputService.selectDate(input.value);
      });

      // directly set the value by js
      input.addEventListener('c-input__input-valueset', (e) => {
        dateInputService.selectDate(input.value);
      });

      if (this.hasAttribute('value')) {
        dateInputService.selectDate(this.getAttribute('value'));
      }

      // fix datepicker dialog won't scroll inside overlay-scroll
      this.closest('.scroll-overlay-y')?.addEventListener('scroll', (e) => {
        dateInputService.renewDatePickerPosition();
      });
    }

    // checkbox
    if (this.isCheckbox) {
      this.checkBoxRadioService.renderCheckboxRadio('checkbox', this);

      input.addEventListener('change', (e) => {
        this.checked = input.checked;
        // dispatch input's native change event
        // thus can, e.g., trigger xxx() in <c-input onchange="xxxx()">
        this.dispatchEvent(new Event('change'));
      });
    }

    // radio
    if (this.isRadio) {
      this.checkBoxRadioService.renderCheckboxRadio('radio', this);

      const radioContainer = this.closest('.radio-group');
      // if (!radioContainer) {
      //   alert('radio input must be placed inside <div class="radio-group"></div>');
      // }

      const name = this.getAttribute('name');
      if (!name) {
        alert('name attribute is required for radio input');
      }
      input.addEventListener('change', (e) => {
        // clear all
        this.checkBoxRadioService.clearRadioGroup();
        // set checked
        input.checked = true;
        this.internals_.setFormValue(input.value);

        // dispatch input's native change event
        // thus can, e.g., trigger xxx() in <c-input onchange="xxxx()">
        this.dispatchEvent(new Event('change'));
      });
    }
  }

  #clearInput(input) {
    this.valueBeforeChange = input.value;
    if (this.isCheckBox) {
      input.checked = false;
    } else {
      input.value = '';
    }
    input.dispatchEvent(new Event('input', { composed: true }));

    // bubbles: true option makes the event bubble up through the DOM, and composed: true option allows the event to pass through shadow DOM boundaries.
    let event = new CustomEvent('c-input__input-cleared', { bubbles: true, composed: false });
    input.dispatchEvent(event);

    // 模擬input 觸發onchange事件
    this.valueAfterChange = input.value;
    if (this.valueBeforeChange !== this.valueAfterChange) {
      this.dispatchEvent(new Event('change'));
    }
  }

  /**
   * Copies attributes from one element to another.
   * @param {HTMLElement} targetEle - The target element to copy attributes to.
   * @param {string} baseClass - The base class to add to the target element.
   * @param {string} name - The name of the attribute to copy.
   * @param {string|null} newValue - The new value of the attribute.
   */
  #copyAttributes(targetEle, baseClass, name, newValue) {
    if (name === "class") {
      targetEle.classList.remove(...targetEle.classList);
      targetEle.classList.add(baseClass, ...newValue.split(' '));
    } else {
      if (newValue === null) {
        targetEle.removeAttribute(name);
      } else {
        targetEle.setAttribute(name, newValue);
      }
    }
  }

  #getDateFormat() {
    if (this.isMonthPicker && this.getAttribute('dateFormat')) {
      alert('attribute `dateFormat` is not supported for month picker');
    }

    if (this.isMonthPicker) {
      return 'yyyy/MM';
    }

    if (this.isYearPicker) {
      return 'yyyy';
    }

    return this.getAttribute('dateFormat')
        ? this.getAttribute('dateFormat')
        : 'yyyy/MM/dd';
  }

  /**
   *  removes invalid characters from the input value.
   */
  #sanitizeValue(value) {
    if (!value) return value;

    if (typeof value !== 'string') {
      return value;
    }

    const sanitizedValue = value
      .replace(/\u00A0/g, ''); // remove non-breaking space (NBSP)

    return sanitizedValue;
  }

  get value() {
    const input = this.shadowRoot.querySelector('.c-input__input');
    return input?.value;
  }

  set value(value) {
    const sanitizedValue = this.#sanitizeValue(value);
    const input = this.shadowRoot.querySelector('.c-input__input');
    input.value = sanitizedValue;
    this.internals_.setFormValue(sanitizedValue);
    let event = new CustomEvent('c-input__input-valueset', { bubbles: true, composed: false });
    input.dispatchEvent(event);
  }

  get checked() {
    const input = this.shadowRoot.querySelector('.c-input__input');
    return input?.checked;
  }

  set checked(value) {
    const input = this.shadowRoot.querySelector('.c-input__input');
    if (value) {
      // clear all
      this.checkBoxRadioService.clearRadioGroup();
    }
    input.checked = value;
    if (value === false) {
      this.removeAttribute('cchecked');
      this.internals_.setFormValue(null);
    } else {
      this.setAttribute('cchecked', '');
      if (!this.disabled) {
        this.internals_.setFormValue(input.value);
      }
    }
  }

  get disabled() {
    const input = this.shadowRoot.querySelector('.c-input__input');
    return input?.disabled;
  }

  set disabled(value) {
    const input = this.shadowRoot.querySelector('.c-input__input');
    input.disabled = value;

    if (value) {
      this.setAttribute('disabled', '');
    } else {
      this.removeAttribute('disabled');
    }

    // clear form internals if disabled
    if (value) {
      this.internals_.setFormValue(null);
    } else {
      if ((this.isRadio || this.isCheckbox)) {
        if (this.checked) {
          this.internals_.setFormValue(input.value);
        }
        return;
      }
      // 一般 input
      this.internals_.setFormValue(input.value);
    }
  }

  get ele() {
    return {
      input: this.shadowRoot.querySelector('.c-input__input'),
    }
  }

  get readOnly() {
    const input = this.shadowRoot.querySelector('.c-input__input');
    return input.readOnly;
  }

  set readOnly(value) {
    const input = this.shadowRoot.querySelector('.c-input__input');
    input.readOnly = value;
    if (value) {
      this.setAttribute('readonly', '');
    } else {
      this.removeAttribute('readonly');
    }
  }

  click() {
    const input = this.shadowRoot.querySelector('.c-input__input');
    input.click();
  }
}
