import CsfdsHTMLElement from "../CsfdsHTMLElement";
import html from "./CsfdsSidemenu.html";
import css from "./CsfdsSidemenu.scss";
import OverlayScrollbar from '../../scss/overlay-scrollbar/OverlayScrollbar';
import OverlayScrollbarCss from '!css-loader!sass-loader!../../scss/overlay-scrollbar/OverlayScrollbar.scss';

import {appendRippleSpan} from '../../scss/ripple/ripple';
import rippleCss from '!css-loader!sass-loader!../../scss/ripple/_ripple.scss';


export default class CsfdsSidemenu extends CsfdsHTMLElement {
  static define() {
    customElements.define("c-sidemenu", CsfdsSidemenu);
  }

  titleHtml = `
    <li class="menu-accordion">
      <button class="menu-accordion__title menu__item"><span class="menu-accordion__arrow"></span>
      </button>
      <ul class="menu-accordion__panel">
      </ul>
    </li>
  `;

  itemHtml = `<li class="menu__item"><a href="f300/f304/applyBadList" target="c">法金申請轉列呆帳清冊</a></li>`;

  footerHtml = `<li class="menu-footer"></li>`;

  constructor() {
    super();

    this.html = html;
    this.css = css + OverlayScrollbarCss + rippleCss;
    this.canSearch = true;
  }

  connectedCallback() {
    super.connectedCallback(this.html.trim(), this.css);

    if (this.hasAttribute('logo-src')) {
      const logoImg = this.shadowRoot.querySelector('.logo img');
      logoImg.src = this.getAttribute('logo-src');
    }

    if (this.hasAttribute('logo-href')) {
      const logoImg = this.shadowRoot.querySelector('.logo img');
      logoImg.addEventListener('click', () => {
        top.window.location.href = this.getAttribute('logo-href');
      });
    }

    // add input search
    const searchInput = this.shadowRoot.querySelector('c-input.search');
    searchInput.addEventListener('compositionstart', () => {
      this.canSearch = false;
    });
    searchInput.addEventListener('input', () => {
      if (this.canSearch) {
        this.#doSearch(searchInput.value);
      }
    });
    searchInput.addEventListener('compositionend', (e) => {
      this.canSearch = true;
      searchInput.dispatchEvent(new Event('input', {composed: true}));
    });
  }

  focusSearch() {
    this.shadowRoot.querySelector('c-input.search').focus();
  }

  initMenuItems(menuItems) {
    for (const menuItem of menuItems) {
      this.#initMenuItem(menuItem);
    }

    const footer = super.createElement(this.footerHtml);
    this.shadowRoot.querySelector('.scroll-body').append(footer);

    // menu-accordion__title 點下去時作動
    const self = this;
    this.shadowRoot.querySelectorAll("button.menu-accordion__title").forEach(el => {
      el.addEventListener("click", function () {
        if (el.closest('.menu-accordion').classList.contains('open')) {
          self.#closeMenu(el);
        } else {
          // waitForTransition=false, 因為想child,parent一起展開
          self.#openMenu(el, false);
        }
      });
    });

    // scroll overlay
    new OverlayScrollbar(this.shadowRoot.querySelector('.scroll-overlay-y'));

    // add ripple effect to menu titles
    this.shadowRoot.querySelectorAll('button.menu__item').forEach(item => {
      item.addEventListener('click', (e) => {
        const parentLi = item.closest('li.menu-accordion');
        appendRippleSpan(item, parentLi, e.clientX, e.clientY);
      });
    });
    // menu item 點下去時切換 active class, 並且加上 ripple effect
    const menuItemEles = this.shadowRoot.querySelectorAll("li.menu__item");
    menuItemEles.forEach(el => {
      el.addEventListener("click", function (e) {
        // toggle active class
        menuItemEles.forEach(el => {
          el.classList.remove("active");
        });
        el.classList.add("active");
      });

      el.addEventListener("mousedown", (e) => {
        // ripple effect
        const parentLi = el.closest('ul.menu-accordion__panel');
        if (parentLi === null) {
          console.warn('menu-accordion__panel not found');
          return;
        }
        appendRippleSpan(el, el, e.clientX, e.clientY);
      });
    });
  }

  // 動態長menu-items
  #initMenuItem(menuItem, parentId = 0, level = 0) {
    // title
    if (menuItem.type?.toLowerCase() === 'group') {
      // if doesn't have children, skip
      if (!hasChildren(menuItem)) {
        return;
      }

      const title = super.createElement(this.titleHtml);
      title.querySelector('button').prepend(menuItem.textContent);
      title.firstElementChild.id = 'menu-title-' + menuItem.id;

      if (parentId === 0) {
        this.shadowRoot.querySelector('.scroll-body').append(title);
      } else {
        const parentTitle = this.shadowRoot.querySelector('#menu-title-' + parentId);
        parentTitle.querySelector('.menu-accordion__panel').append(title);
      }
      // item
    } else if (menuItem.type?.toLowerCase() === 'item') {
      const item = super.createElement(this.itemHtml);
      item.querySelector('a').textContent = menuItem.textContent;
      item.querySelector('a').href = menuItem.href ?? "undefined";
      item.querySelector('a').setAttribute('data-value', menuItem.sysFunction ?? "undefined");
      item.querySelector('li.menu__item').id = 'menu-item-' + menuItem.id;
      item.querySelector('li.menu__item').title = menuItem.textContent;
      item.querySelector('li.menu__item').classList.add('lvl-' + level);

      const parentTitle = this.shadowRoot.querySelector('#menu-title-' + parentId);
      parentTitle.querySelector('.menu-accordion__panel').append(item);
    } else {
      console.warn('menu type not found');
    }

    if (menuItem.children) {
      for (const child of menuItem.children) {
        this.#initMenuItem(child, menuItem.id, level + 1);
      }
    }

    function hasChildren(menuItem) {
      if (!menuItem.children || menuItem.length === 0) {
        return false;
      }

      // 可能有group底下又有group，但第二層group底下都沒有item
      let hasItemChild = false;
      for (const childMenuItem of menuItem.children) {
        if (childMenuItem.type?.toLowerCase() === 'item') {
          hasItemChild = true;
          break;
        }

        if (hasChildren(childMenuItem)) {
          hasItemChild = true;
          break;
        }
      }

      return hasItemChild;
    }
  }

  async #doSearch(searchValue) {
    const matchItems = this.#filterMenuItems(searchValue);
    if (searchValue) {
      // 從最內層展開
      for (const item of matchItems) {
        // 展開父母
        const titleBtn = item.closest('.menu-accordion').querySelector('.menu-accordion__title');
        this.#openMenu(titleBtn);

        // 展開阿公阿嬤 (如有)
        const parentAccordion = item.closest('.menu-accordion')?.parentElement.closest('.menu-accordion');
        if (parentAccordion) {
          const parentTitleBtn = parentAccordion.querySelector('.menu-accordion__title');
          this.#openMenu(parentTitleBtn);
        }

        // 展開阿奏 (如有)
        const grandParentAccordion = parentAccordion?.parentElement.closest('.menu-accordion');
        if (grandParentAccordion) {
          const grandParentTitleBtn = grandParentAccordion.querySelector('.menu-accordion__title');
          this.#openMenu(grandParentTitleBtn);
        }
      }
    } else {
      // collapse all menu items
      for (const titleBtn of this.shadowRoot.querySelectorAll('button.menu-accordion__title')) {
        this.#closeMenu(titleBtn);
      }
    }
  }

  // filter menu items
  #filterMenuItems(searchText) {
    let matchedItems = [];

    const menuItems = this.shadowRoot.querySelectorAll('li.menu__item');
    menuItems.forEach(item => {
      if (item.textContent.toLowerCase().includes(searchText.toLowerCase())) {
        item.style.display = 'block';
        matchedItems.push(item);
      } else {
        item.style.display = 'none';
      }
    });

    return matchedItems;
  }

  // 裡面會呼叫#expandMenu
  async #openMenu(titleBtn, waitForTransition = true) {
    const accor = titleBtn.closest(".menu-accordion");
    if (accor === null) {
      return;
    }

    accor.classList.remove("open");
    accor.classList.add("open");

    const panel = accor.querySelector(".menu-accordion__panel");
    if (panel === null) {
      return;
    }

    this.#expandMenu(panel, 0, waitForTransition);
  }

  // 裡面會呼叫#expandMenu
  async #closeMenu(titleBtn) {
    const accor = titleBtn.closest(".menu-accordion");
    if (accor === null) {
      return;
    }

    accor.classList.remove("open");

    const panel = accor.querySelector(".menu-accordion__panel");
    if (panel === null) {
      return;
    }

    await this.#expandMenu(panel);
  }

  async #expandMenu(panel, childScrollHeight = 0, waitForTransition = true) {
    const accor = panel.closest(".menu-accordion");
    const totalScrollHeight = childScrollHeight + panel.scrollHeight;
    if (accor.classList.contains("open")) {
      panel.style.maxHeight = totalScrollHeight + "px";
    } else {
      panel.style.maxHeight = null;
    }

    if (waitForTransition) {
      await this.#waitForTransition(panel);
    }

    // expand parent
    const parentPanel = panel.parentElement.closest(".menu-accordion__panel");
    if (parentPanel === null) {
      return;
    }

    await this.#expandMenu(parentPanel, totalScrollHeight);
  }

  /**
   * 等待 CSS transition 結束
   */
  #waitForTransition(element) {
    let resolveCalled = false;
    return new Promise(resolve => {
      const handleTransitionEnd = (e) => {
        if (e.target === element && e.propertyName === 'max-height') {
          element.removeEventListener('transitionend', handleTransitionEnd);
          resolveCalled = true;
          resolve();
        }
      };

      element.addEventListener('transitionend', handleTransitionEnd);

      // Fallback timeout in case transition doesn't fire
      setTimeout(() => {
        if (resolveCalled) return;
        element.removeEventListener('transitionend', handleTransitionEnd);
        resolveCalled = true;
        resolve();
      }, 200);
    });
  }
}
