import tippy from "tippy.js";
import 'tippy.js/dist/tippy.css';
import 'tippy.js/animations/scale-subtle.css';
import './custom-theme.css';

document.addEventListener('DOMContentLoaded', () => {
  tippy('[data-tooltip]', {
    content: (target) => target.getAttribute('data-tooltip'),
    trigger: 'mouseenter',
    theme: 'macle',
    arrow: true,
    allowHTML: true,
    delay: [200, 30], // show tooltip after 200ms, hide after 30ms
    duration: [100, 20], // fade in/out duration
    offset: [20, 3], // move tooltip 20px to the right and 3px down
    inertia: true,
    animation: 'scale-subtle',
    maxWidth: 300,
  });
});
