import html from './CsfdsButton.html';
import css from './CsfdsButton.scss'
import { appendRippleSpan } from '../../scss/ripple/ripple';
import CsfdsHTMLElement from '../CsfdsHTMLElement';

export default class CsfdsButton extends CsfdsHTMLElement {
  static observedAttributes = ["class"];

  constructor() {
    super();
    this.rendered = false;
  }

  connectedCallback() {
    super.connectedCallback(html.trim(), css);
    if (!this.rendered) {
      this.#render();
      this.rendered = true;
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    // console.log('Attribute changed: ' + name + ' | ' + oldValue + ' | ' + newValue);

    if (this.shadowRoot) {
      const button = this.shadowRoot.querySelector('button');
      if (name === 'class') {
        // copy class attribute from host to shadow root
        if (button) {
          button.classList.remove(...button.classList);
          button.classList.add('c-btn', ...this.classList);
        }
      }
    }
  }

  #render() {
    // handle <a> button
    let a = this.querySelector('a');
    if (a) {
      a.setAttribute('tabindex', '-1');

      // move <a> element from light DOM to shadow DOM
      const frontContainer = this.shadowRoot.querySelector('.c-btn .front')
      frontContainer.appendChild(a);
      this.shadowRoot.querySelector('slot')?.remove();

      // click .front also trigger a.click()
      frontContainer.addEventListener('click', (e) => {
        // if front is clicked, but not because of <a>'s click bubbling up
        // add this check to prevent <c-button> triggering click twice
        if (e.currentTarget == e.target) {
          e.stopPropagation(); // only propagate <a>'s click event
          a.click();
        }
      });
    }

    const button = this.shadowRoot.querySelector('button');

    // copy class attribute from host to shadow root
    this.classList.forEach(className => {
      button.classList.add(className);
    });
    if (this.hasAttribute('disabled')) {
      button.setAttribute('disabled', '');
    }

    // handle type=submit button, when clicked then submit the form
    const isSubmitButton = this.getAttribute('type') === 'submit';
    if (isSubmitButton && button) {
      button.setAttribute('type', 'submit');
      button.addEventListener('click', () => {
        // this.internals_.form.submit(); // this won't trigger form submit eventListener
        // this.closest('form').dispatchEvent(new Event('submit')); // this won't actually submit the form
        // so I have to use this:
        this.closest('form').requestSubmit();
      });
    }
    
    // handle type=reset button, when clicked then reset the form
    const isResetButton = this.getAttribute('type') === 'reset';
    if (isResetButton && button) {
      button.setAttribute('type', 'reset');
      button.addEventListener('click', () => {
        this.closest('form').reset();
        this.closest('form').querySelectorAll('c-input, c-select').forEach(input => {
          input.reset();
        });

        // bubbles: true option makes the event bubble up through the DOM, and composed: true option allows the event to pass through shadow DOM boundaries.
        let event = new CustomEvent('reset', { bubbles: true, composed: false });
        this.closest('form').dispatchEvent(event);
      });
    }

    this.#registerRippleEffectOnClick();
  }


  #controller = new AbortController();

  #registerRippleEffectOnClick() {
    const buttons = this.shadowRoot.querySelectorAll('.c-btn:not([disabled]) .front');
    buttons.forEach(btn => {
      btn.addEventListener('click', (e) => {
        const parentCbtn = e.target.closest('button.c-btn');
        appendRippleSpan(btn, parentCbtn, e.clientX, e.clientY);
      }, { signal: this.#controller.signal });
    });
  }

  #unregisterRippleEffect() {
    this.#controller.abort();
    this.#controller = new AbortController();
  }

  get disabled() {
    return this.hasAttribute('disabled');
  }

  set disabled(value) {
    const button = this.shadowRoot.querySelector('button');
    if (value) {
      this.setAttribute('disabled', '');
      button.setAttribute('disabled', '');
      this.#unregisterRippleEffect();
    } else {
      this.removeAttribute('disabled');
      button.removeAttribute('disabled');
      this.#registerRippleEffectOnClick();
    }
  }
}
