/**
 * move original inner elements to slot
 *
 * say we have a custom element like this:
 * <my-comp>
 *  <div>original content</div>
 *  <div>original content</div>
 * </my-comp>
 *
 * and the template of my-comp is like this:
 * let html = `<div>
 *              <h1>hello</h1>
 *              <slot></slot>
 *             </div>`
 *
 * then the result will be:
 * <my-comp>
 *  <div>
 *   <h1>hello</h1>
 *   <div>original content</div>
 *   <div>original content</div>
 *  </div>
 * </my-comp>
 *
 * @param {HTMLTemplateElement} template
 * @param {HTMLElement} theComponent
 * @param {boolean} removeToBeSlottedWrapper - remove the wrapper, e.g. <div slot="header">...</div> itself, leaving only the content
 */
export function moveToSlot(template, theComponent, removeToBeSlottedWrapper = false) {
  // if no named slot, move to default slot
  if (!theComponent.querySelector('[slot]')) {

    // move original inner content to fragment first
    let fragment = new DocumentFragment();
    while (theComponent.firstChild) {
      fragment.appendChild(theComponent.firstChild);
    }

    // replace slot with fragment
    let slot = template.content.querySelector('slot');
    slot.replaceWith(fragment);

  } else {
    // if there are named slot, move to named slot
    let toBeSlottedEles = theComponent.querySelectorAll('[slot]');
    let tempFragments = []; // [{ slotName: 'slot1', fragment: DocumentFragment }]
    for (let i = 0; i < toBeSlottedEles.length; i++) {
      let ele = toBeSlottedEles[i];
      let slotName = ele.getAttribute('slot');
      let slot = template.content.querySelector(`slot[name=${slotName}]`);
      if (!slot) {
        console.error(`No slot found with name: ${slotName}`);
        return;
      }

      // check slotName already in tempFragments
      let fragment = tempFragments.find(f => f.slotName === slotName);
      if (!fragment) {
        let slotFragment = new DocumentFragment();
        fragment = { slotName, fragment: slotFragment };
        tempFragments.push(fragment);
      }

      // move ele to fragment
      if (removeToBeSlottedWrapper) {
        for (let i = 0; i < ele.childNodes.length;) {
          fragment.fragment.appendChild(ele.childNodes[i]);
        }
        ele.remove();
      } else {
        fragment.fragment.appendChild(ele);
      }
    }

    // replace slot with fragment
    for (let i = 0; i < tempFragments.length; i++) {
      let { slotName, fragment } = tempFragments[i];
      let slot = template.content.querySelector(`slot[name=${slotName}]`);
      slot.replaceWith(fragment);
    }
  }

  return template;
}

/**
 * append css to head, id is used to check if the css is already appended
 */
export function appendCssToHead(cssStr, id) {
  let style = document.createElement('style');
  style.id = id;
  style.innerHTML = cssStr;
  const existingStyle = document.head.querySelector(`#${id}`);
  if (!existingStyle) {
    document.head.appendChild(style);
  }
}


export function getFirstFocusableElement(ele) {
  const focusableEles = ele.querySelectorAll('button, c-button, [href], c-input, input, select, c-select, textarea, [tabindex]:not([tabindex="-1"])');
  let firstFocusableEle = null;
  for (let i = 0; i < focusableEles.length; i++) {
    let el = focusableEles[i];
    if (!el.classList.contains('d-none')
      && !el.hasAttribute('disabled')
      && !(el.style.display === 'none')) {
      firstFocusableEle = el;
      break;
    }
  }

  return firstFocusableEle;
}
