export default class CsfdsHTMLElement extends HTMLElement {
  constructor() {
    super();
  }

  connectedCallback(htmlStr, cssStr) {
    if (!this.shadowRoot) {
      this.attachShadow({mode: 'open', delegatesFocus: true});
      this.initHtml(htmlStr);
      this.initCss(cssStr);
    }
  }

  createElement(htmlStr) {
    const template = document.createElement('template');
    template.innerHTML = htmlStr;
    return template.content.cloneNode(true);
  }

  initHtml(htmlStr) {
    this.shadowRoot.innerHTML = htmlStr;
  }

  initCss(cssStr) {
    const style = new CSSStyleSheet();
    style.replaceSync(cssStr);
    this.shadowRoot.adoptedStyleSheets = [style];
  }
}
