import html from './CsfdsTable.html';
import styles from './CsfdsTable.scss'

/**
 * Deprecated
 */
export default class CsfdsTable extends HTMLElement {
  static observedAttributes = ["class", "type"];

  constructor() {
    super();

    this.shadow = this.attachShadow({ mode: 'open' });
    this.styleSheet = new CSSStyleSheet();
  }

  // mounted
  connectedCallback() {
    this.render();
  }

  render() {
    this.shadow.innerHTML = html.trim();
    this.styleSheet.replaceSync(styles);
    this.shadow.adoptedStyleSheets = [this.styleSheet];
    this.style.display = 'block';

    // move table from light DOM to shadow DOM
    let table = this.querySelector('table');
    if (table === null) {
      alert('<table> element is required for the slot');
      return;
    }
    this.shadow.querySelector('.c-table .table-container').prepend(table);

    // copy classes from host to shadow root
    const cTable = this.shadow.querySelector('.c-table');
    cTable.classList.remove(...cTable.classList);
    cTable.classList.add('c-table', ...this.classList);

    // pagination
    const paginationContainer = this.shadow.querySelector('.pagination .pagination-inner');
    if (this.pageCount > 0) {
      if (this.pageCount > 1) {
        // buttons
        let previousButton = document.createElement('c-button');
        previousButton.setAttribute('class', 'btn-sm');
        previousButton.textContent = '<';
        if (!this.hasPreviousPage) {
          // previousButton.style.visibility = 'hidden';
          previousButton.setAttribute('disabled', '');
        } else {
          previousButton.addEventListener('click', () => {
            this.dispatchPageChangeEvent(this.currentPage - 1);
          });
        }
        paginationContainer.append(previousButton);

        let pageButtons = this.calcPageButtons(this.currentPage, this.pageCount);
        pageButtons.forEach(pageButton => {
          paginationContainer.append(pageButton);
        });

        let nextButton = document.createElement('c-button');
        nextButton.setAttribute('class', 'btn-sm');
        nextButton.textContent = '>';
        if (!this.hasNextPage) {
          // nextButton.style.visibility = 'hidden';
          nextButton.setAttribute('disabled', '');
        } else {
          nextButton.addEventListener('click', () => {
            this.dispatchPageChangeEvent(this.currentPage + 1);
          });
        }
        paginationContainer.append(nextButton);

        // dropdown
        let pagesDropdown = document.createElement('c-select');
        pagesDropdown.setAttribute('class', 'input-sm icon-none');
        for (let i = 1; i <= this.pageCount; i++) {
          let option = document.createElement('option');
          option.value = i;
          option.text = `第 ${i} 頁`;
          if (i === this.currentPage) {
            option.setAttribute('selected', '');
          }
          pagesDropdown.appendChild(option);
        }
        pagesDropdown.setAttribute('size', 5);
        pagesDropdown.addEventListener('change', (e) => {
          this.dispatchPageChangeEvent(e.target.value);
        });
        paginationContainer.append(pagesDropdown);
      }

      // pageinfo span
      let pageInfoSpan = document.createElement('span');
      pageInfoSpan.textContent = this.pageInfoText;
      pageInfoSpan.style.marginLeft = '2px';
      paginationContainer.append(pageInfoSpan);
    }
  }

  copyAttributes(targetEle, baseClass, name, newValue) {
    if (name === "class") {
      targetEle.classList.remove(...targetEle.classList);
      targetEle.classList.add(baseClass, ...newValue.split(' '));
    } else {
      if (newValue === null) {
        targetEle.removeAttribute(name);
      } else {
        targetEle.setAttribute(name, newValue);
      }
    }
  }

  // truncate long text and add ellipsis (...)
  ellipse(str, n) {
    return (str.length > n) ? str.slice(0, n - 1) + ' ...' : str;
  };

  // calculate page buttons
  calcPageButtons(currentPage, pageCount) {
    let pageButtons = [];
    if (pageCount <= 5) {
      for (let i = 1; i <= pageCount; i++) {
        pageButtons.push(this.createPageButton(i, currentPage));
      }
    } else {
      if (currentPage <= 3) {
        for (let i = 1; i <= 5; i++) {
          pageButtons.push(this.createPageButton(i, currentPage));
        }
      } else if (currentPage >= pageCount - 2) {
        for (let i = pageCount - 4; i <= pageCount; i++) {
          pageButtons.push(this.createPageButton(i, currentPage));
        }
      } else {
        for (let i = currentPage - 2; i <= currentPage + 2; i++) {
          pageButtons.push(this.createPageButton(i, currentPage));
        }
      }
    }

    return pageButtons;
  }

  createPageButton = (i, currentPage) => {
    let pageButton = document.createElement('c-button');
    pageButton.setAttribute('class', 'btn-sm btn-secondary');
    pageButton.textContent = i;
    if (i === currentPage) {
      pageButton.classList.add('active');
    }

    pageButton.addEventListener('click', () => {
      if (i === currentPage) {
        return;
      }

      this.dispatchPageChangeEvent(i);
    });
    return pageButton;
  }

  // dispatch event, so it can be listened like this:
  // <c-table-wrapper onchange="console.log(this.value.newPage)" ...
  dispatchPageChangeEvent = (newPage) => {
    let event = new Event('change');
    this.value = { newPage: newPage };
    this.dispatchEvent(event);
  }

  get pageCount() {
    const pageCount = this.getAttribute('pageCount');
    if (pageCount === null) {
      return 0;
    }

    if (isNaN(parseInt(pageCount))) {
      return 0;
    }

    return parseInt(pageCount);
  }

  get currentPage() {
    const currentPage = this.getAttribute('currentPage');
    if (currentPage === null) {
      return 1;
    }

    if (isNaN(parseInt(currentPage))) {
      return 1;
    }

    return parseInt(currentPage);
  }

  get newPage() {
    this.value?.newPage ?? 1;
  }

  get totalRows() {
    const totalRows = this.getAttribute('totalRows');
    if (totalRows === null) {
      return 0;
    }

    if (isNaN(parseInt(totalRows))) {
      return 0;
    }

    return parseInt(totalRows);
  }

  get hasPreviousPage() {
    return this.currentPage !== 1;
  }

  get hasNextPage() {
    return this.currentPage !== this.pageCount;
  }

  // e.g., 211~217 (共 217 筆)
  get pageInfoText() {
    let start = (this.currentPage - 1) * 10 + 1;
    let end = this.currentPage === this.pageCount ? this.totalRows : this.currentPage * 10;

    return `${start}~${end} (共 ${this.totalRows} 筆)`;
  }
}
