import "./OverlayScrollbar.scss";

export default class OverlayScrollbar {

  /**
   * @param scrollOverlayY {HTMLElement} - element with class .scroll-overlay-y
   */
  constructor(scrollOverlayY) {
    this._barMarginY = 5; // 5px
    this.init(scrollOverlayY);
  }

  init(scrollOverlayY) {
    // if scrollOverlayY is not set, init all scrollOverlayYs on DOM
    let scrollOverlayYs = [];
    if (scrollOverlayY) {
      scrollOverlayYs.push(scrollOverlayY);
    } else {
      scrollOverlayYs = document.querySelectorAll(".scroll-overlay-y");
    }

    scrollOverlayYs.forEach(el => {
      if (el.querySelector("div.scrollbar-track") != null) {
        return;
      }

      // set .scroll-overlay-y position to relative
      const elPositionType = window.getComputedStyle(el).position;
      if (elPositionType !== "absolute" && elPositionType !== "relative") {
        el.style.position = "relative";
      }

      const scrollBody = el.querySelector(".scroll-body");
      if (scrollBody === null) {
        alert(".scroll-body must be set together with .scroll-overlay-y");
        return;
      }

      const track = document.createElement("div");
      track.classList.add("scrollbar-track");

      const thumb = document.createElement("div");
      thumb.classList.add("scrollbar-thumb");
      track.appendChild(thumb);

      this.initOverlayScrollBar(el, scrollBody, track, thumb);
      el.prepend(track);
    });
  }

  initOverlayScrollBar(parent, scrollBody, track, thumb) {
    this.updateThumb(parent, track, thumb);

    // handle native scroll event
    parent.addEventListener('scroll', () => this.updateThumb(parent, track, thumb));

    // handle parent resize event
    new ResizeObserver((e) => this.updateThumb(parent, track, thumb))
      .observe(parent);
    new ResizeObserver((e) => this.updateThumb(parent, track, thumb)).observe(scrollBody);


    // handle thumb drag event
    let mouseY;
    let relativeThumbTop = 0;
    thumb.addEventListener('mousedown', function (e) {
      if (e.button !== 0) return;
      e.preventDefault()
      mouseY = e.clientY
      relativeThumbTop = parseFloat(thumb.style.top) - parent.scrollTop;

      document.addEventListener('mousemove', drag);
      document.addEventListener('mouseup', end);
    });

    function drag(e) {
      e.preventDefault()

      relativeThumbTop = relativeThumbTop + e.clientY - mouseY;

      let maxRelatedBarTop = track.clientHeight - thumb.clientHeight;
      let minBarTop = 0;
      if (relativeThumbTop > maxRelatedBarTop) relativeThumbTop = maxRelatedBarTop;
      if (relativeThumbTop < minBarTop) relativeThumbTop = minBarTop;

      let percentage = relativeThumbTop / track.clientHeight;
      parent.scrollTop = parent.scrollHeight * percentage;
      mouseY = e.clientY;
    }

    function end(e) {
      document.removeEventListener('mouseup', end)
      document.removeEventListener('mousemove', drag)
    }
  }

  updateThumb(parent, track, thumb) {
    if (parent.scrollHeight > parent.clientHeight) {
      track.style.display = "block";
    } else {
      track.style.display = "none";
    }

    thumb.style.height = track.clientHeight * (parent.clientHeight / parent.scrollHeight) + 'px'

    let newTop = parent.scrollTop + track.clientHeight * (parent.scrollTop / parent.scrollHeight);
    let maxTop = parent.scrollHeight - thumb.clientHeight - 2 * this._barMarginY;
    thumb.style.top = newTop > maxTop ? maxTop + 'px' : newTop + 'px';
  }
}
