/** 全版overlay */
c-action-bar[fit-content] .action-bar-area {
  display: inline-block;
}

c-action-bar .action-bar {
  margin-bottom: 0.5rem;
  margin-left: auto;
  margin-right: auto;
  padding: 4px 10px;
  border-radius: 5px;
  background: var(--c-background-gray-light-1);
  font-size: var(--c-noraml-font-size);
  box-shadow: var(--c-table-box-shadow-light);
  display: flex;
  flex-wrap: wrap;
  column-gap: 6px;
  row-gap: 6px;
}
