  position: relative;
  padding-right: 6px;
  margin-right: 6px;
}
c-action-bar .action-bar div.separator::after {
  content: "";
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 1.5px;
  height: 80%;
  border-radius: 5px;
  background-color: #c2c2c2;
}
