  align-items: center;
  justify-content: center;
  column-gap: 0.2rem;
  border-radius: 5px;
  outline: none;
  border: none;
  padding: 3px 5px;
  cursor: pointer;
  font-size: var(--c-noraml-font-size);
  transition: all 150ms linear;
}
c-action-bar .action-bar button c-svg {
  color: var(--c-slate-600);
}
c-action-bar .action-bar button:disabled {
  background-color: #f4f4f4;
  color: #bbbbbb;
  transition: all 60ms linear;
