import html from './CsfdsLoader.html';
import css from './CsfdsLoader.scss'
import CsfdsHTMLElement from '../CsfdsHTMLElement';

export default class CsfdsLoader extends CsfdsHTMLElement {
  constructor() {
    super();

    this.rendered = false;

    this.loaderTimeout = null;
    this.isShown = false;
  }

  connectedCallback() {
    super.connectedCallback(html.trim(), css);

    if (!this.rendered) {
      this.render();
      this.rendered = true;
    }
  }

  render() {
    this.loaderContainer = this.shadowRoot.querySelector('.container');
  }

  // default timeout 180 secs
  show(msg = 'Loading...', ms = 180000) {
    if (this.isShown) {
      console.log('%c already shown', 'font-size:1.5em;color:crimson');
      return;
    }

    this.isShown = true;
    document.activeElement.blur();
    this.loaderContainer.classList.remove('hidden');
    this.loaderContainer.querySelector('.loading-message').textContent = msg;

    this.loaderTimeout = setTimeout(() => {
      alert('timeout');
      this.hide('setTimeout');
    }, ms);
  }

  hide() {
    if (!this.isShown) {
      return;
    }

    this.isShown = false;
    try {
      clearTimeout(this.loaderTimeout);
    } catch (err) {
      console.log('%c clearTimeout error', 'font-size:1.5em;color:crimson');
    }
    const loaderContainer = this.shadowRoot.querySelector('.container');
    loaderContainer.classList.add('hidding');
    const listener = loaderContainer.addEventListener('animationend', function (evt) {
      if (evt.animationName === 'fade-out') {
        loaderContainer.classList.remove('hidding');
        loaderContainer.classList.add('hidden');
        loaderContainer.removeEventListener('animationend', listener);
      }
    });
  }
}
