import htmlStr from './CsfdsModal.html';
import cssStr from './CsfdsModal.scss';
import {appendCssToHead, moveToSlot} from "../../utils/web-comp-utils";
import {generateUUID} from "../../utils/utils";
import _CsfdsModalHeader from "./_CsfdsModalHeader";
import _CsfdsModalBody from "./_CsfdsModalBody";
import _CsfdsModalFooter from "./_CsfdsModalFooter";

/**
 * Events:
 *  c-modal-open: when the modal is opened
 *  c-modal-close: when the modal is closed
 *
*  Public methods:
 *  open(data = {}, showOverlay = true): open the modal
 *  close(data = {}, hideOverlay = true): close the modal
 *  closeAndOpen(nextModal, data = {}): close the current modal and open the next modal
 */
export default class CsfdsModal extends HTMLElement {
  #componentUuid = generateUUID();

  static define() {
    customElements.define('c-modal-header', _CsfdsModalHeader);
    customElements.define('c-modal-body', _CsfdsModalBody);
    customElements.define('c-modal-footer', _CsfdsModalFooter);
    customElements.define('c-modal', CsfdsModal);
  }

  constructor() {
    super();
    this.style.display = 'none';
  }

  get hasRendered() {
    return this.getAttribute('rendered');
  }

  set hasRendered(val) {
    this.setAttribute('rendered', val);
  }

  get icon() {
    return this.getAttribute('icon');
  }

  set icon(val) {
    this.setAttribute('icon', val);
    this.#changeIcon(val);
  }

  get noClose() {
    return this.hasAttribute('no-close')
      || (this.getAttribute('no-close') === 'true');
  }

  set noClose(val) {
    if (val) {
      this.setAttribute('no-close', '');
    } else {
      this.removeAttribute('no-close');
    }
  }

  /**
   * show the modal
   *
   * @param {Object} data the data to be passed to the modal
   * @param {Object} options the options to be passed to the modal
   *  {boolean} showOverlay - whether to show the overlay
   */
  open(data = {}, showOverlay = true) {
    if (data === null) { data = {}; }

    // show overlay
    if (showOverlay) {
      this.querySelector('.bg-overlay-container').classList.remove('d-none');
    }

    // show modal
    this.querySelector('.c-modal').classList.remove('d-none');

    this.dispatchEvent(new CustomEvent('c-modal-open', {
      detail: data
    }));
  }

  /**
   * close the modal
   *
   * @param {Object} data - the data to be passed to the parent component
   */
  close(data = {}, hideOverlay = true) {
    if (data === null) { data = {}; }

    if (hideOverlay) {
      this.querySelector('.bg-overlay-container').classList.add('d-none');
    }
    this.querySelector('.c-modal').classList.add('hiding');

    // hide the modal after 100ms
    setTimeout(() => {
      if (hideOverlay) {
        this.querySelector('.bg-overlay-container').classList.add('d-none');
        this.querySelector('.bg-overlay-container').classList.remove('hiding');
      }

      this.querySelector('.c-modal').classList.add('d-none');
      this.querySelector('.c-modal').classList.remove('hiding');

      this.dispatchEvent(new CustomEvent('c-modal-close', {
        detail: data
      }));
    }, 100);
  }

  /**
   * close the current modal and open the next modal
   * 多加這個方法因為不希望切換modal時，背景overlay會閃一下
   *
   * @param {CsfdsModal} nextModal - the next modal to open
   * @param {Object} data - the data to be passed to the next modal
   */
  closeAndOpen(nextModal, data = {}) {
    if (data === null) { data = {}; }

    this.close(data, false);
    setTimeout(() => {
      nextModal.open(data, false);
    }, 100);
  }

  connectedCallback() {
    if (!this.hasRendered) {
      this.innerHTML = this.#constructHtml(htmlStr);
      appendCssToHead(cssStr, 'csfds-modal-style');

      this.style.display = 'block';

      // bind event listeners
      // when click outside the .c-modal, close the modal
      if (!this.noClose) {
        this.querySelector('.bg-overlay-container').addEventListener('click', () => {
          this.close();
        });
      }
      // when click on the close button, close the modal
      this.querySelector('.c-modal-close').addEventListener('click', () => {
        this.close();
      });

      this.hasRendered = true;
    }
  }

  #constructHtml(htmlStr) {
    let template = document.createElement('template');
    template.innerHTML = htmlStr;

    // get <c-modal-header>, <c-modal-body>, <c-modal-footer> elements
    const modalHeader = this.querySelector('c-modal-header');
    const modalBody = this.querySelector('c-modal-body');
    const modalFooter = this.querySelector('c-modal-footer');
    // check if they exist
    if (!modalHeader || !modalBody || !modalFooter) {
      console.error('c-modal must have <c-modal-header>, <c-modal-body>, <c-modal-footer> elements');
    }

    // show icon
    if (this.icon) {
      template.content.querySelector(`.c-modal-header .${this.icon}`).classList.remove('d-none');
    }

    // hide close button if no-close attribute
    if (this.noClose) {
      template.content.querySelector('.c-modal-close').classList.add('d-none');
    }

    modalHeader.setAttribute('slot', 'header');
    modalBody.setAttribute('slot', 'body');
    modalFooter.setAttribute('slot', 'footer');
    moveToSlot(template, this, true);

    return template.innerHTML;
  }

  #changeIcon(val) {
    document.querySelectorAll('.icon').forEach(icon => {
      icon.classList.add('d-none');
    });
    if (val) {
      if (!this.querySelector(`.icon.${val}`)) {
        console.error(`No icon found with class: ${val}`);
        return;
      }
      this.querySelector(`.icon.${val}`).classList.remove('d-none');
    }
  }
}
