3YI;EACE,qCAAA;AA6YN;AA1YI;EACE,qCAAA;AA4YN;AAvYE;EACE,uCAAA;AAyYJ;AAxYI;EACE,gBAAA;EACA,2BAAA;AA0YN;AAtYE;EAEE,sCAAA;AAuYJ;;AAlYA;EACE,kBAAA;EACA,oBAAA;EACA,kBAnFkB;EAoFlB,mBDtDK;ECuDL,uBAAA;EACA,YAAA;EACA,gEAAA;EAEA,gBAAA;EACA,iBAAA;EAEA,mBAAA;EAGA,2BAAA;EACA,2BAAA;EACA,gBAAA;AAiYF;AA/XE;EACE,cAAA;EACA,qBAAA;EACA,oBAAA;AAiYJ;AA/XI;EACE,qBAAA;EACA,oBAAA;EACA,oBAAA;EACA,gBAAA;AAiYN;AA5XE;EAEE,2BAAA;EACA,0BAAA;AA6XJ;AA1XE;EACE,2BAAA;EACA,oEAAA;AA4XJ;AAzXE;EACE,8BDrHK;ACgfT;AAxXE;EACE,cAAA;EACA,mBAAA;AA0XJ;;AArXA;EACE,kBAAA;EACA,MAAA;EACA,OAAA;EACA,YAAA;EACA,WAAA;EACA,2BAAA;EACA,kBA9IkB;EA+IlB,iBAAA;EACA,sBAAA;EACA,0BAAA;EACA,2BAAA;AAwXF;AArXE;EAEE,0BAAA;EACA,2BAAA;AAsXJ;AAlXE;EACE,0BAAA;EACA,0BAAA;AAoXJ;;AA/WA;EACE,kBAAA;EACA,MAAA;EACA,OAAA;EACA,YAAA;EACA,WAAA;EACA,kBAzKkB;EA0KlB,wFAAA;AAkXF;AA5WE;EACE,wFAAA;AA8WJ;AAvWE;EACE,wFAAA;AAyWJ;AAlWE;EACI,wFAAA;AAoWN;;AA1VE;EACE,wBAAA;EACA,iBAAA;EACA,2BAAA;AA6VJ;AA1VE;EACE,0BAAA;AA4VJ;;AAtVE;EACE,qBAAA;EACA,sBAAA;AAyVJ","sourcesContent":["@use \"sass:map\";\r\n\r\n$primary-dark-1: hsl(183, 100%, 22%);\r\n$primary-dark-2: hsl(183, 100%, 20%);\r\n$primary-l1: hsl(183, 100%, 28%);\r\n$primary-light-2: hsl(183, 100%, 40%);\r\n$primary-light-4: hsl(183, 45%, 90%);\r\n$primary-light-5: hsl(192, 50%, 96%); // from sfap\r\n$primary-blueish: hsl(193, 96%, 31%);\r\n$sfap-header-bg: hsl(182, 98%, 25%);\r\n$sfap-table-bg: hsl(183, 100%, 25%); // 最深\r\n$sfap-tab-color: hsl(182, 59%, 36%);\r\n$sfap-bell-bg: hsl(180, 65%, 33%); // 小鈴鐺\r\n$sfap-btn-bg: hsl(171, 41%, 51%); // 感覺隨便選的，有點青蘋果綠\r\n\r\n$danger: hsl(359, 82%, 55%); // 從首頁來\r\n$danger-pinkish: hsl(337, 92%, 49%); // gradient\r\n\r\n$secondary: hsl(183, 91%, 17%);\r\n\r\n// use $c as the shorthand for csfds\r\n// $c: (\r\n//   ) $primary: hsl(183, 100%, 25%\r\n//   );\r\n$primary: hsl(183, 100%, 25%);\r\n$primary-50: mix(white, $primary-light-4, 70%);\r\n$primary-80: mix(white, $primary, 66%);\r\n$primary-100: mix(white, $primary, 56%);\r\n$primary-200: mix(white, $primary, 42%);\r\n$primary-300: mix(white, $primary, 28%);\r\n$primary-400: mix(white, $primary, 14%);\r\n$primary-500: $primary;\r\n$primary-600: mix(black, $primary, 12%);\r\n$primary-700: mix(black, $primary, 24%);\r\n$primary-800: mix(black, $primary, 36%);\r\n$primary-900: mix(black, $primary, 50%);\r\n\r\n$cyan: mix(rgb(61, 140, 210), $primary, 30%);\r\n$cyan-50: mix(white, #cbe8f0, 70%);\r\n$cyan-80: #cbe8f0;\r\n$cyan-100: mix(white, $cyan, 56%);\r\n$cyan-200: mix(white, $cyan, 42%);\r\n$cyan-300: mix(white, $cyan, 28%);\r\n$cyan-400: mix(white, $cyan, 14%);\r\n$cyan-500: $cyan;\r\n$cyan-600: mix(black, $cyan, 12%);\r\n$cyan-700: mix(black, $cyan, 24%);\r\n$cyan-800: mix(black, $cyan, 36%);\r\n$cyan-900: mix(black, $cyan, 50%);\r\n\r\n// borrowed from tailwindcss\r\n$c: (\r\n  primary: (\r\n    50: $primary-50,\r\n    80: $primary-light-4,\r\n    100: $primary-100,\r\n    200: $primary-200,\r\n    300: $primary-300,\r\n    400: $primary-400,\r\n    500: $primary,\r\n    600: $primary-600,\r\n    700: $primary-700,\r\n    800: $primary-800,\r\n    900: $primary-900,\r\n  ),\r\n  \"cyan\": (\r\n    50: $cyan-50,\r\n    80: $cyan-80,\r\n    100: $cyan-100,\r\n    200: $cyan-200,\r\n    300: $cyan-300,\r\n    400: $cyan-400,\r\n    500: $cyan,\r\n    600: $cyan-600,\r\n    700: $cyan-700,\r\n    800: $cyan-800,\r\n    900: $cyan-900,\r\n  ),\r\n  slate: (\r\n    50: #f8fafc,\r\n    100: #f1f5f9,\r\n    200: #e2e8f0,\r\n    300: #cbd5e1,\r\n    350: #afbdd0,\r\n    400: #94a3b8,\r\n    500: #64748b,\r\n    600: #475569,\r\n    700: #334155,\r\n    800: #1e293b,\r\n    900: #0f172a,\r\n  ),\r\n  rose: (\r\n    50: #fff1f2,\r\n    100: #ffe4e6,\r\n    200: #fecdd3,\r\n    300: #fda4af,\r\n    400: #fb7185,\r\n    500: #f43f5e,\r\n    600: #e11d48,\r\n    700: #be123c,\r\n    800: #9f1239,\r\n    900: #4c0519,\r\n  )\r\n);\r\n\r\n// generate --c-slate-100, --c-slate-200... css properties\r\n:root {\r\n  --c-danger: hsl(359, 82%, 55%);\r\n  --c-blue-1: rgb(55, 150, 190);\r\n\r\n  @each $colorname, $palette in $c {\r\n    @each $key, $value in $palette {\r\n      // --c is the prefix for csfds variables\r\n      $keyname: \"--c-\" + $colorname + \"-\" + $key;\r\n      #{$keyname}: #{$value};\r\n    }\r\n  }\r\n}\r\n\r\n// generate .bg-slate-100, .bg-slate-200... css classes\r\n.bg {\r\n  @each $colorname, $palette in $c {\r\n    @each $key, $value in $palette {\r\n\r\n      // --c is the prefix for csfds variables\r\n      &-#{$colorname}-#{$key} {\r\n        background-color: var(--c-#{$colorname}-#{$key});\r\n\r\n        @if $colorname ==primary and $key >=400 {\r\n          color: white;\r\n        }\r\n\r\n        @else if $colorname ==\"cyan\" and $key >=500 {\r\n          color: white;\r\n        }\r\n\r\n        @else if $colorname ==slate and $key >=500 {\r\n          color: white;\r\n        }\r\n\r\n        @else if $colorname ==rose and $key >=600 {\r\n          color: white;\r\n        }\r\n\r\n        @else {\r\n          color: black;\r\n        }\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n// generate .text-cyan-100, .text-rose-200... css classes\r\n.text {\r\n  @each $colorname, $palette in $c {\r\n    @each $key, $value in $palette {\r\n      // if $colorname == \"slate\", skip (專案初期有專門的.text-slate-xxx了，就仍先以那邊為主)\r\n      @if $colorname == \"slate\" {\r\n        @continue;\r\n      }\r\n\r\n      // --c is the prefix for csfds variables\r\n      &-#{$colorname}-#{$key} {\r\n        color: var(--c-#{$colorname}-#{$key});\r\n      }\r\n    }\r\n  }\r\n}\r\n","@use \"sass:meta\";\r\n@use '../../scss/colors' as colors;\r\n@use '../../scss/variables' as variables;\r\n@use '../../scss/ripple/ripple';\r\n\r\n$primary: colors.$cyan;\r\n$secondary: lighten(colors.$secondary, 4%);\r\n$btn-border-radius: 8px;\r\n\r\n\r\n// svg icon的位置\r\n// svg 要下載16*16的icon\r\n::slotted(svg) {\r\n  display: inline-block;\r\n  pointer-events: none;\r\n  // 往下一咪咪\r\n  transform: translateY(1px);\r\n}\r\n\r\n// button 那層\r\n.c-btn {\r\n  position: relative;\r\n  padding: 0;\r\n  border: none;\r\n  cursor: pointer;\r\n  transition: filter 250ms;\r\n  outline: none; // prevent outline when focus on button\r\n  border-radius: $btn-border-radius;\r\n\r\n  // 當Hover時調亮\r\n  &:focus:not([disabled]),\r\n  &:hover:not([disabled]),\r\n  &:active:not([disabled]),\r\n  &.active:not([disabled]) {\r\n    filter: brightness(116%);\r\n\r\n    &.btn-danger {\r\n      filter: brightness(110%);\r\n    }\r\n\r\n    &.btn-secondary {\r\n      filter: brightness(108%);\r\n    }\r\n\r\n    &.btn-info {\r\n      filter: brightness(105%);\r\n    }\r\n  }\r\n\r\n  // 當Focus時，加上邊框\r\n  &:focus {\r\n    \r\n    .shadow {\r\n      display: none;\r\n    }\r\n\r\n    outline: 3px solid var(--c-primary-300);\r\n\r\n    &.btn-danger {\r\n      outline: 3px solid var(--c-rose-300);\r\n    }\r\n\r\n    &.btn-secondary {\r\n      outline: 3px solid var(--c-slate-350);\r\n    }\r\n\r\n    &.btn-info {\r\n      outline: 3px solid var(--c-slate-300);\r\n    }\r\n  }\r\n\r\n  // manual active state\r\n  &.btn-secondary.active:not([disabled]) {\r\n    outline: 3px solid var(--c-primary-300);\r\n    .front {\r\n      font-weight: 700;\r\n      color: var(--c-primary-700);\r\n    }\r\n  }\r\n\r\n  &[disabled] {\r\n    // filter: saturate(30%) brightness(130%);\r\n    filter: contrast(40%) brightness(130%);\r\n  }\r\n}\r\n\r\n// Button表層(含文字那層)\r\n.front {\r\n  position: relative;\r\n  display: inline-flex;\r\n  border-radius: $btn-border-radius;\r\n  background: $primary; // 版本1\r\n  padding: 0.25rem 0.5rem;\r\n  color: white;\r\n  font-family: #{meta.inspect(variables.$font-family-a)};\r\n  // font-weight: 600; // 版本1\r\n  font-weight: 500;\r\n  font-size: .8rem;\r\n\r\n  white-space: nowrap;\r\n  \r\n  // transform: translateY(-4px); // 浮起來的高度 // 版本1\r\n  transform: translateY(-2px); // 浮起來的高度\r\n  transition: transform 100ms;\r\n  overflow: hidden;\r\n\r\n  a {\r\n    color: inherit;\r\n    text-decoration: none;\r\n    display: inline-flex;\r\n\r\n    svg {\r\n      display: inline-block;\r\n      vertical-align: -4px;\r\n      pointer-events: none;\r\n      margin: 0 .2rem;\r\n    }\r\n  }\r\n\r\n  // 點下去時往下移，沉下去效果\r\n  .c-btn:not([disabled]) &:active {\r\n    // transform: translateY(-2px); // 版本1\r\n    transform: translateY(-1px);\r\n    transition: transform 50ms;\r\n  }\r\n\r\n  .btn-secondary & {\r\n    color: var(--c-primary-500);\r\n    background: linear-gradient(30deg, hsl(0, 0%, 92%), hsl(0, 0%, 98%));\r\n  }\r\n\r\n  .btn-danger & {\r\n    background: colors.$danger;\r\n  }\r\n\r\n  .btn-info & {\r\n    color: #6c6c6c;\r\n    background: #e0e0e0;\r\n  }\r\n}\r\n\r\n// 淡淡的Shadow\r\n.shadow {\r\n  position: absolute;\r\n  top: 0;\r\n  left: 0;\r\n  height: 100%;\r\n  width: 100%;\r\n  background: hsl(0, 0%, 60%);\r\n  border-radius: $btn-border-radius;\r\n  filter: blur(2px);\r\n  will-change: transform;\r\n  transform: translateY(1px);\r\n  transition: transform 100ms;\r\n\r\n  // hover時，陰影變大，浮起來效果\r\n  .c-btn:hover:not([disabled]) & {\r\n    // transform: translateY(4px); // 版本1\r\n    transform: translateY(3px);\r\n    transition: transform 250ms;\r\n  }\r\n\r\n  // 點下去時，陰影變小，沉下去效果\r\n  .c-btn:active:not([disabled]) & {\r\n    transform: translateY(1px);\r\n    transition: transform 50ms;\r\n  }\r\n}\r\n\r\n// 深色的底層\r\n.edge {\r\n  position: absolute;\r\n  top: 0;\r\n  left: 0;\r\n  height: 100%;\r\n  width: 100%;\r\n  border-radius: $btn-border-radius;\r\n  background: linear-gradient(to right,\r\n      darken(colors.$primary-l1, 12%) 0%,\r\n      darken(colors.$primary-l1, 9%) 8%,\r\n      darken(colors.$primary-blueish, 9%) 92%,\r\n      darken(colors.$primary-blueish, 12%) 100%);\r\n\r\n  .btn-secondary & {\r\n    background: linear-gradient(to right,\r\n        darken(hsl(0, 0%, 85%), 20%) 0%,\r\n        darken(hsl(0, 0%, 85%), 12%) 8%,\r\n        darken(hsl(0, 0%, 95%), 12%) 92%,\r\n        darken(hsl(0, 0%, 95%), 20%) 100%);\r\n  }\r\n\r\n  .btn-danger & {\r\n    background: linear-gradient(to right,\r\