export default class _CsfdsTab extends HTMLElement {
  static define() {
    customElements.define('c-tab', _CsfdsTab);
  }

  connectedCallback() {
    this.style.display = 'none';
  }

  get title() {
    return this.getAttribute('title');
  }

  get maxHeight() {
    return this.getAttribute('maxHeight');
  }
}
