export function copyAttributes(targetEle, baseClass, name, oldValue, newValue) {
  if (name === "class") {
    targetEle.classList.remove(...targetEle.classList);
    targetEle.classList.add(baseClass, ...newValue.split(' '));
  } else {
    if (newValue === null) {
      targetEle.removeAttribute(name);
    } else {
      targetEle.setAttribute(name, newValue);
    }
  }
}

export function getStyleSheet(style) {
  let styleSheet = new CSSStyleSheet();
  styleSheet.replaceSync(style);
  return [styleSheet];
}

export function hasSibling(node) {
  return node.nextElementSibling || node.previousElementSibling;
}

/**
 * 等待ms後resolve
 *
 * @param ms
 * @returns {Promise<unknown>}
 */
export async function waitMs(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * 檢查node是否有同類型的兄弟節點
 *
 * @param type 'checkbox' or 'radio'
 */
export function hasSiblingOfSameType(node, type) {
  // 兄弟是否同tag, 譬如說都是<c-input>
  const isSiblingSameTag = node.nextElementSibling?.tagName === node.tagName
                                   || node.previousElementSibling?.tagName === node.tagName;
  if (!isSiblingSameTag) {
    return false;
  }

  if (type === null) {
    return true;
  }

  const isSiblingSameTypeAttri =
     node.nextElementSibling?.getAttribute('type') === type
  || node.previousElementSibling?.getAttribute('type') === type;
  return isSiblingSameTypeAttri;
}

export function isChildOf(node, parent) {
  return parent.contains(node);
}


/**
 * 產uuid
 *
 * @returns {string} e.g., 6d06f78c-61d3-4544-a9ff-d701a7258c30
 */
export function generateUUID() {
  return ([1e7]+-1e3+-4e3+-8e3+-1e11).replace(/[018]/g, c =>
    (c ^ crypto.getRandomValues(new Uint8Array(1))[0] & 15 >> c / 4).toString(16)
  );
}

export function arrayEqual(arr1, arr2, ignoreOrder = false) {
  if (arr1.length !== arr2.length) return false;

  if (ignoreOrder) {
    arr1 = [...arr1].sort();
    arr2 = [...arr2].sort();
  }

  for (let i = 0; i < arr1.length; i++) {
    if (arr1[i] !== arr2[i]) return false;
  }
  return true;
}

/**
 *  讓function被連續觸發時，只在最後一次觸發後的隔段時間執行，防止大量觸發
 *
 *  @param func {Function} 要執行的函數
 *  @param wait {Number} 一段時間(毫秒)
 *  @param immediate {Boolean} 是否先立即執行一次
 *
 *  @example
 *  function sayHi(userName) { console.log(`hi ${userName}`); }
 *  const sayHiDebounced = debounce((userName) => sayHi(userName), 1000);
 *
 *  // 60次觸發，只會執行1次，在最後一次觸發後的1秒後執行
 *  for (let i = 0; i < 60; i++) {
 *    await wait(20);
 *    sayHiDebounced('Alice');
 *  }
 */
export function debounce(func, wait, immediate = false) {
  let timeoutId;
  return function() {
    const context = this;
    const args = arguments;
    const later = function() {
      timeoutId = null;
      if (!immediate) func.apply(context, args);
    };
    const callNow = immediate && !timeoutId;
    clearTimeout(timeoutId);
    timeoutId = setTimeout(later, wait);
    if (callNow) func.apply(context, args);
  };
}
