export default class CsfdsActionBarService {

  prependSvgToButtons(btns, svgName) {
    if (btns && btns.length) {
      btns.forEach(btn => {
        this.prependSvgToButton(btn, svgName);
      });
    }
  }

  prependSvgToButton(btn, svgName) {
    if (btn && !btn.querySelector('c-svg')) {
      const svg = document.createElement('c-svg');
      svg.setAttribute('svgName', svgName);
      btn.prepend(svg);
    }
  }

  setDataTooltips(btns, tooltip) {
    if (btns && btns.length) {
      btns.forEach(btn => {
        this.setDataTooltip(btn, tooltip);
      });
    }
  }

  setDataTooltip(btn, tooltip) {
    if (btn && !btn.getAttribute('data-tooltip')) {
      btn.setAttribute('data-tooltip', tooltip);
    }
  }
}
