export class StateService {
  constructor(component) {
    this.component = component;
    this.state = {
      value: '',
      values: [],
      selectedIndex: -1,
      disabled: false,
      readonly: false,
      multiple: false,
      searchable: false,
      dropdownOpen: false,
      isComposing: false,
      isSearching: false,
      labelsAndValues: [], // [{ label: 'option1', value: '1' }]
      recentValue: '', // last set value using before change value check changeEvent
      recentValues: [] // todo: multiple select equal recentValue
    };
  }

  getRecentValue() {
    return this.state.recentValue;
  }

  /**
   * 特定情況同步當前變更值
   */
  syncRecentValue() {
    this.state.recentValue = this.getValue();
  }

  // value accessors
  getValue() {
    return this.state.value;
  }

  setValue(value) {
    this.state.value = String(value) || '';
    this.component.formService.setFormValue(String(value));
  }

  getValues() {
    return this.state.values;
  }

  setValues(values) {
    this.state.values = Array.isArray(values) ? values : [];
    this.updateLabelsAndValuesFromValues();
    this.updateFormValues();
  }

  addValue(value) {
    if (!this.state.values.includes(value)) {
      this.state.values.push(value);
      this.updateFormValues();
    }
  }

  removeValue(value) {
    this.state.values = this.state.values.filter(v => v !== value);
    this.state.labelsAndValues = this.state.labelsAndValues.filter(item => item.value !== value);
    this.updateFormValues();
  }

  clearValues() {
    this.state.values = [];
    this.state.labelsAndValues = [];
    this.updateFormValues();
  }

  updateFormValues() {
    this.component.formService.setMultipleFormValues(this.state.values);
  }

  // selection accessors
  getSelectedIndex() {
    return this.state.selectedIndex;
  }

  setSelectedIndex(index) {
    this.state.selectedIndex = index;
  }

  getLabelsAndValues() {
    return this.state.labelsAndValues;
  }

  setLabelsAndValues(labelsAndValues) {
    this.state.labelsAndValues = labelsAndValues;
    this.state.values = labelsAndValues.map(item => item.value);
    this.updateFormValues();
  }

  addLabelAndValue(label, value) {
    // don't add duplicates
    if (!this.state.labelsAndValues.some(item => item.value === value)) {
      this.state.labelsAndValues.push({label, value});
      this.addValue(value);
    }
  }

  updateLabelsAndValuesFromValues() {
    const dropdownItems = [...document.querySelectorAll(`#${this.component.dropdownId} li.option`)];

    // keep existing labels for values that are still in the values array
    const newLabelsAndValues = [];

    this.state.values.forEach(value => {
      // try to find existing label first
      const existing = this.state.labelsAndValues.find(item => item.value === value);

      if (existing) {
        newLabelsAndValues.push(existing);
      } else {
        // find from dropdown items
        const item = dropdownItems.find(item => item.getAttribute('value') === value);
        if (item) {
          newLabelsAndValues.push({
            label: item.textContent.trim(),
            value
          });
        }
      }
    });

    this.state.labelsAndValues = newLabelsAndValues;
  }

  // boolean state accessors
  isDisabled() {
    return this.state.disabled;
  }

  setDisabled(disabled) {
    this.state.disabled = !!disabled;
  }

  isReadonly() {
    return this.state.readonly;
  }

  setReadonly(readonly) {
    this.state.readonly = !!readonly;
  }

  isMultiple() {
    return this.state.multiple;
  }

  setMultiple(multiple) {
    this.state.multiple = !!multiple;
  }

  isSearchable() {
    return this.state.searchable;
  }

  setSearchable(searchable) {
    this.state.searchable = !!searchable;
  }

  isDropdownOpen() {
    return this.state.dropdownOpen;
  }

  setDropdownOpen(open) {
    const wasOpen = this.state.dropdownOpen;
    this.state.dropdownOpen = !!open;

    // update dropdown visibility
    const dropdown = document.getElementById(this.component.dropdownId);
    if (!dropdown) return;

    const dropdownIcon = this.component.shadowRoot.querySelector('.dropdown-icon');

    if (open) {
      // opening the dropdown
      if (!wasOpen) {
        this.component.domService.setupPositionListeners();

        // dispatch before-open event
        this.component.dispatchEvent(new Event('c-select-before-open', {
          bubbles: true,
          composed: true
        }));
      }

      dropdown.classList.add('open');
      if (dropdownIcon) dropdownIcon.classList.add('open');

      // focus search input if searchable
      if (this.state.searchable) {
        const searchInput = dropdown.querySelector('.search input');
        if (searchInput) searchInput.focus();
      } else {
        // focus main input
        const input = this.component.shadowRoot.querySelector('.c-input__input');
        if (input) input.focus();
      }

      // dispatch open event
      this.component.dispatchEvent(new Event('c-select-open', {
        bubbles: true,
        composed: true
      }));
    } else {
      // closing the dropdown
      dropdown.classList.remove('open');
      dropdown.classList.remove('open-top');
      if (dropdownIcon) dropdownIcon.classList.remove('open');

      // clear search input if searchable
      if (this.state.searchable) {
        const searchInput = dropdown.querySelector('.search input');
        if (searchInput) {
          searchInput.value = '';
          searchInput.dispatchEvent(new Event('input'));
        }
      }

      // dispatch close event
      this.component.dispatchEvent(new Event('c-select-close', {
        bubbles: true,
        composed: true
      }));
    }
  }

  isComposing() {
    return this.state.isComposing;
  }

  setIsComposing(isComposing) {
    this.state.isComposing = !!isComposing;
  }

  isSearching() {
    return this.state.searching;
  }

  setIsSearching(searching) {
    this.state.searching = !!searching;
  }

  // get selected items
  getSelected() {
    if (this.state.multiple) {
      return this.state.labelsAndValues;
    } else {
      return this.state.value ? [{value: this.state.value}] : [];
    }
  }
}
