// Register click event for ripple effect
// for ripple to work, button must have overflow: hidden, and position: relative
export function appendRippleSpan(btn, btnContainer, clickClientX, clickClientY) {
  if (btnContainer === null) {
    alert('btnContainer should not be null');
    return;
  }

  // btn.style.overflow = 'hidden'; // weird on firefox
  btn.style.position = 'relative';

  let x = clickClientX - btnContainer.getBoundingClientRect().left;
  let y = clickClientY - btnContainer.getBoundingClientRect().top;

  let ripple = document.createElement('span');
  if (btn.clientWidth > 200) {
    ripple.classList.add('ripple-large');
  } else {
    ripple.classList.add('ripple');
  }
  ripple.classList.add('ripple');
  ripple.style.left = x + 'px';
  ripple.style.top = y + 'px';
  // set ripple color to text's color
  ripple.style.backgroundColor = window.getComputedStyle(btn).getPropertyValue('color');

  // TODO: without hardcode .menu-item
  if (btn.classList.contains('menu__item')) {
    ripple.style.backgroundColor = 'var(--c-cyan-300)';
  }

  btn.appendChild(ripple);

  // remove ripple after animation end
  setTimeout(() => {
    ripple.remove()
  }, 2000);
}