.container {
  position: fixed;
  top: 0px;
  left: 0px;
  width: 100%;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  user-select: none;
  overscroll-behavior: contain;
  z-index: 999;
}
.container .bg-overlay {
  position: absolute;
  top: 0px;
  left: 0px;
  background-color: rgba(0, 0, 0, 0.3);
  width: 100%;
  min-height: 100vh;
  z-index: 999;
  animation: bg-overlay-fade-in 3000ms ease-in-out forwards;
}
.container.hidding {
  animation: fade-out 200ms ease-in-out forwards;
}
.container.hidden {
  display: none;
}

@keyframes fade-out {
  from {
    opacity: 0.4;
  }
  to {
    opacity: 0;
  }
}
.loader {
  width: 100%;
  height: 200px;
  background-color: rgb(250, 250, 250);
  animation: loader-fade-in 800ms 200ms ease-in-out forwards;
  z-index: 1000;
  opacity: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  align-content: center;
  flex-wrap: wrap;
  gap: 3px 3px;
  transform: translateY(-15px);
}

@keyframes bg-overlay-fade-in {
  from {
