  position: relative;
  animation: loading-bar-fade-in 700ms 2600ms ease-in-out forwards;
  opacity: 0;
}
.loading-bar::after {
  content: "";
  width: 100px;
  height: 3px;
  position: absolute;
  top: 0px;
  background-color: var(--c-primary-300);
  animation: loading-bar 3.5s ease-in-out infinite;
}

@keyframes loading-bar {
  0% {
    transform: translateX(235px);
  }
  50% {
    transform: translateX(-105px);
  }
  100% {
    transform: translateX(235px);
  }
}
@keyframes loading-bar-fade-in {
  from {
    transform: translateY(5px);
    opacity: 0;
  }
  to {
    transform: translateY(0px);
    opacity: 1;
  }
}
.loading-logo {
