import OverlayScrollbars from '../../../scss/overlay-scrollbar/OverlayScrollbar';
import { templates } from '../templates.js';

export class DomService {
  constructor(component) {
    this.component = component;
    this.scrollableParents = [];
    this.updatePositionBound = this.updateDropdownPosition.bind(this);
    this.optionObservers = []; // for tracking mutation observers
  }

  createDropdown(template) {
    // create dropdown and append to body
    const dropdown = document.createElement('div');
    dropdown.classList.add('c-input__dropdown');
    dropdown.setAttribute('id', this.component.dropdownId);
    dropdown.setAttribute('tabindex', '-1');

    if (this.component.stateService.isSearchable()) {
      dropdown.setAttribute('searchable', '');
    }

    dropdown.innerHTML = template;
    document.body.appendChild(dropdown);

    // initialize scrollbar
    this.initScrollbar(dropdown);

    return dropdown;
  }

  removeDropdown() {
    const dropdown = document.getElementById(this.component.dropdownId);
    if (dropdown) {
      document.body.removeChild(dropdown);
    }
  }

  /**
   * 當dropdown的 display 是 none
   * 用 getBoundingClientRect() 方法抓不到正確資料
   * 把display設成block 才能抓到視窗資訊
   */
  getDropdownClientRect(dropdown) {
    if (!dropdown) return;

    // 先保留原始樣式
    const resetStyles = {
      display: dropdown.style.display,
      visibility: dropdown.style.visibility,
      position: dropdown.style.position,
      zIndex: dropdown.style.zIndex
    };

    // 套用隱藏的樣式
    const styles = {
      display: 'block',
      visibility: 'hidden',
      position: 'absolute',
      zIndex: '-999'
    };

    Object.assign(dropdown.style, styles);

    const dropdownRect = dropdown.getBoundingClientRect();

    // 拿完 ClientRect 恢復dropdown屬性
    Object.assign(dropdown.style, resetStyles);

    return dropdownRect;
  }

  initScrollbar(dropdown) {
    const scrollContainer = dropdown.querySelector('.scroll-overlay-y');
    if (scrollContainer) {
      new OverlayScrollbars(scrollContainer);
    }
  }

  applyStyles(componentStyles, dropdownStyles) {
    // apply component styles
    const componentStyleSheet = new CSSStyleSheet();
    componentStyleSheet.replaceSync(componentStyles);
    this.component.shadowRoot.adoptedStyleSheets = [
      ...this.component.shadowRoot.adoptedStyleSheets,
      componentStyleSheet
    ];

    // apply dropdown styles globally
    const globalStyleSheet = new CSSStyleSheet();
    globalStyleSheet.replaceSync(dropdownStyles);
    document.adoptedStyleSheets = [
      ...document.adoptedStyleSheets,
      globalStyleSheet
    ];
  }

  /**
   * 取得 <option> 元素們，這些元素放在 <c-select> 裡面，如:
   * <c-select>
   *     <option value="1">Option 1</option>
   *     <option value="2">Option 2</option>
   * </c-select>
   */
  getOptionsFromSlot() {
    const slot = this.component.shadowRoot.querySelector('slot:not([name])');
    return [...slot.assignedElements()].filter(
      node => node.nodeType !== Node.TEXT_NODE && node.tagName.toLowerCase() === 'option'
    );
  }

  getSearchInput() {
    return document.querySelector(`#${this.component.dropdownId} .search input`);
  }

  getDropdownItems() {
    return document.querySelectorAll(`#${this.component.dropdownId} li.option`);
  }

  getDropdownContainer() {
    return document.getElementById(this.component.dropdownId);
  }

  renderDropdownItems() {
    const dropdown = this.getDropdownContainer();
    if (!dropdown) return;

    const optionsContainer = dropdown.querySelector('ul.options');
    optionsContainer.innerHTML = '';

    const isMultiple = this.component.stateService.isMultiple();
    if (isMultiple) {
      optionsContainer.toggleAttribute('multiple', true);
    }

    const slotOptions = this.getOptionsFromSlot();

    slotOptions.forEach(option => {
      const value = option.getAttribute('value') || '';
      const label = option.textContent.trim();
      const selected = option.hasAttribute('selected');

      const itemHtml = templates.dropdownItem({ value, label, selected });
      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = itemHtml;
      const item = tempDiv.firstElementChild;

      // TODO: item.prepend(iconcheckmark); ???

      // add tooltip for long text
      if (label.length > 10) {
        item.title = label;
      }

      optionsContainer.appendChild(item);
    });

    // set up event listeners for the new items
    this.component.eventService.setupDropdownItemListeners();

    // set up mutation observers for selected attribute changes
    this.setupMutationObservers();

  }

  selectDefaultItems() {
    const isMultiple = this.component.stateService.isMultiple();
    const input = this.component.shadowRoot.querySelector('.c-input__input');
    const dropdownItems = this.getDropdownItems();
    const slotOptions = this.getOptionsFromSlot();

    // find options with 'selected' attribute
    let defaultSelectedOptions = [...slotOptions].filter(
      option => option.hasAttribute('selected')
    );

    // if not found, use default ele's value
    if (defaultSelectedOptions.length === 0) {
      defaultSelectedOptions = [...slotOptions].filter(
        option => option.getAttribute('value') === this.component.stateService.getValue()
      );
    }

    if (isMultiple) {
      // for multiple select, select all default options
      defaultSelectedOptions.forEach(option => {
        const value = option.getAttribute('value');
        const item = [...dropdownItems].find(
          item => item.getAttribute('value') === value
        );

        if (item) {
          this.component.eventService.selectItem(input, item, true, true, false);
        }
      });
    } else {
      // for single select, select the first default option or the first item
      const defaultOption = defaultSelectedOptions[0];

      if (defaultOption) {
        const value = defaultOption.getAttribute('value');
        const item = [...dropdownItems].find(
          item => item.getAttribute('value') === value
        );

        if (item) {
          this.component.eventService.selectItem(input, item, false, true, false);
        }
      } else if (dropdownItems.length > 0) {
        // select first item if no default
        this.component.eventService.selectItem(input, dropdownItems[0], false, true, false);
      }
    }
  }

  updateSelectedItems() {
    const isMultiple = this.component.stateService.isMultiple();
    const selectedValue = this.component.stateService.getValue();
    const selectedValues = this.component.stateService.getValues();
    const dropdownItems = this.getDropdownItems();

    // update dropdown item selection state
    dropdownItems.forEach(item => {
      const value = item.getAttribute('value');
      let isSelected = false;

      if (isMultiple) {
        isSelected = selectedValues.includes(value);
      } else {
        isSelected = selectedValue === value;
      }

      if (isSelected) {
        item.classList.add('selected');
      } else {
        item.classList.remove('selected');
      }
    });

    // update input display
    if (isMultiple) {
      this.updateMultiSelectTags();
    } else {
      this.updateSingleSelectDisplay();
    }
  }

  updateSingleSelectDisplay() {
    const input = this.component.shadowRoot.querySelector('.c-input__input');
    const selectedValue = this.component.stateService.getValue();
    const dropdownItems = this.getDropdownItems();

    const selectedItem = [...dropdownItems].find(
      item => item.getAttribute('value') === selectedValue
    );

    input.value = selectedItem ? selectedItem.textContent.trim() : '';
  }

  updateMultiSelectTags() {
    const tagsContainer = this.component.shadowRoot.querySelector('.tags');
    if (!tagsContainer) {
      // create tags container if it doesn't exist
      const container = document.createElement('div');
      container.classList.add('tags');
      this.component.shadowRoot.querySelector('.c-input').appendChild(container);
      return this.updateMultiSelectTags(); // retry after creating
    }

    const labelsAndValues = this.component.stateService.getLabelsAndValues();

    tagsContainer.innerHTML = '';

    labelsAndValues.forEach(({ label, value }) => {
      const tagHtml = templates.multiSelectTag({ label, value });
      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = tagHtml;
      const tag = tempDiv.firstElementChild;

      tagsContainer.appendChild(tag);

      // add event listener to the close icon
      const closeIcon = tag.querySelector('.icon-close');
      this.component.eventService.setupTagCloseListeners(closeIcon, value);
    });

    // show/hide placeholder based on selection state
    this.togglePlaceholder(labelsAndValues.length > 0);
  }

  togglePlaceholder(hasSelection) {
    const input = this.component.shadowRoot.querySelector('.c-input__input');

    if (!hasSelection) {
      input.style.position = 'static';
    } else {
      input.style.position = 'absolute';
      input.style.left = '-9999px';
    }
  }

  resetSelection() {
    const isMultiple = this.component.stateService.isMultiple();
    const input = this.component.shadowRoot.querySelector('.c-input__input');
    const dropdownItems = this.getDropdownItems();
    const slotOptions = this.getOptionsFromSlot();

    // find default selected options
    const defaultSelectedValues = [...slotOptions]
      .filter(option => option.hasAttribute('selected'))
      .map(option => option.getAttribute('value'));

    // reset dropdown item selection state
    dropdownItems.forEach(item => {
      item.classList.remove('selected');
    });

    if (isMultiple) {
      // for multiple select, select all default options
      defaultSelectedValues.forEach(value => {
        const item = [...dropdownItems].find(
          item => item.getAttribute('value') === value
        );

        if (item) {
          item.classList.add('selected');
        }
      });

      // update state
      this.component.stateService.setValues(defaultSelectedValues);

      // clear all tags and recreate
      const tagsContainer = this.component.shadowRoot.querySelector('.tags');
      if (tagsContainer) {
        tagsContainer.innerHTML = '';
      }

      this.updateMultiSelectTags();
    } else {
      // for single select, select the first default option or the first item
      let selectedItem;

      if (defaultSelectedValues.length > 0) {
        selectedItem = [...dropdownItems].find(
          item => item.getAttribute('value') === defaultSelectedValues[0]
        );
      } else if (dropdownItems.length > 0) {
        selectedItem = dropdownItems[0];
      }

      if (selectedItem) {
        selectedItem.classList.add('selected');
        input.value = selectedItem.textContent.trim();
        this.component.stateService.setValue(selectedItem.getAttribute('value'));
        this.component.stateService.setSelectedIndex([...dropdownItems].indexOf(selectedItem));
      } else {
        input.value = '';
        this.component.stateService.setValue('');
        this.component.stateService.setSelectedIndex(-1);
      }
    }
  }

  /**
   * 先從 DOM 抓畫面上選擇的選項
   * 用這個選項和和記憶體資料做比對
   * state 更新才不會誤判
   */
  getSelectedItem() {
      const dropdownItems = this.getDropdownItems();
      if (dropdownItems) {
        return [...dropdownItems].find(item => {
          // class有selected並且是能被選擇的選項
          return item.classList.contains('selected') && item.style.display !== 'none';
        });
      }
  }

  getArrowSelectItem() {
      const dropdownItems = this.getDropdownItems();
      if (dropdownItems) {
        return [...dropdownItems].find(item => {
          return item.hasAttribute('arrow-select') && item.style.display !== 'none';
        })
      }
  }

  setOptions(options) {
    // clear existing options
    this.component.innerHTML = '';

    // create new options
    options.forEach(option => {
      const optionElement = document.createElement('option');
      optionElement.value = option.value;
      optionElement.textContent = option.label;

      if (option.selected) {
        optionElement.setAttribute('selected', 'selected');
      }

      this.component.appendChild(optionElement);
    });
  }

  updateDropdownPosition(e) {
    if (e) {
      // close dropdown if scrolling outside
      if (e.type === 'scroll' && e.target !== document) {
        if (this.component.stateService.isDropdownOpen()) {
          this.component.stateService.setDropdownOpen(false);
        }
        return;
      }
    }

    const dropdown = this.getDropdownContainer();
    if (!dropdown) return;

    const thisEleRect = this.component.getBoundingClientRect();
    const dropdownRect = this.getDropdownClientRect(dropdown);

    let isNowOpeningAbove = dropdownRect.top < thisEleRect.top; // dropdown is higher than the component
    let isSearching = this.component.stateService.isSearching();
    if (isSearching && isNowOpeningAbove) {
      // keep the dropdown open direction if it's already open and searching
      dropdown.style.top = `${thisEleRect.top - dropdownRect.height - 5}px`;
      return;
    }

    // dropdown 左邊固定對齊 c-select
    dropdown.style.left = `${thisEleRect.left}px`;

    // 判斷dropdown 應該上 dropdownRect.bottom 上方還是下面
    // 計算目前元件到DOM最底部的間距
    const fullHeight = document.documentElement.scrollHeight;
    let aboveSpace = fullHeight - thisEleRect.bottom;

    // 如果是目前視窗能看到的元件
    // 間距是 視窗高度 扣除 當前元件相對視窗上方的位置
    if (thisEleRect.bottom < window.innerHeight) {
      aboveSpace = window.innerHeight - thisEleRect.bottom;
    }

    let newDropdownTop = thisEleRect.bottom + 5;
    const aroundViewBottom = thisEleRect.bottom > window.innerHeight;
    // 起始位置 + dropdown高度 換算 邊界位置
    const dropdownBoundary = newDropdownTop + dropdownRect.height;
    const isNearViewportBottom = dropdownBoundary > (window.innerHeight - 5);

    // dropdown 接近視窗底部，選單在元件上方顯示
    if (isNearViewportBottom || aroundViewBottom) {
      newDropdownTop = thisEleRect.top - dropdownRect.height - 5;
    }

    dropdown.style.top = `${newDropdownTop}px`;
  }

  updateDropdownWidth() {
    const dropdown = this.getDropdownContainer();
    if (!dropdown) return;

    const componentWidth = this.component.getBoundingClientRect().width;
    dropdown.style.width = `${Math.min(componentWidth, 300)}px`;
  }

  setupPositionListeners() {
    // remove existing listeners
    this.removePositionListeners();

    // get scrollable parents
    this.scrollableParents = this.getScrollableParents();

    // add listeners to update dropdown position
    this.scrollableParents.forEach(parent => {
      this.component.eventService.addEventListener(parent, 'scroll', this.updatePositionBound);
    });

    this.component.eventService.addEventListener(window, 'resize', this.updatePositionBound);
  }

  removePositionListeners() {
    this.scrollableParents.forEach(parent => {
      this.component.eventService.removeEventListener(parent, 'scroll', this.updatePositionBound);
    });

    this.component.eventService.removeEventListener(window, 'resize', this.updatePositionBound);
    this.scrollableParents = [];
  }

  getScrollableParents() {
    const scrollableParents = [];
    let parent = this.component.parentElement;

    while (parent) {
      const style = getComputedStyle(parent);
      const overflow = style.overflow + style.overflowY + style.overflowX;

      if (overflow.includes('scroll') || overflow.includes('auto') || overflow.includes('overlay')) {
        scrollableParents.push(parent);
      }

      parent = parent.parentElement;
    }

    scrollableParents.push(window);
    return scrollableParents;
  }

  setupMutationObservers() {
    // disconnect any existing observers first
    this.disconnectMutationObservers();

    // get all option elements
    const slotOptions = this.getOptionsFromSlot();
    if (!slotOptions.length) return;

    // store observers for later cleanup
    this.optionObservers = [];

    // get the input element
    const input = this.component.shadowRoot.querySelector('.c-input__input');
    if (!input) return;

    // observe each option for selected attribute changes
    slotOptions.forEach(option => {
      const observer = new MutationObserver(mutations => {
        mutations.forEach(mutation => {
          if (mutation.type === 'attributes' && mutation.attributeName === 'selected') {
            const isMultiple = this.component.stateService.isMultiple();
            const value = mutation.target.getAttribute('value');
            const dropdownItems = this.getDropdownItems();
            const selectedItem = [...dropdownItems].find(
              item => item.getAttribute('value') === value
            );

            if (!selectedItem) return;

            if (isMultiple) {
              // for multiple select
              const isSelected = mutation.target.hasAttribute('selected');
              this.component.eventService.selectItem(
                input,
                selectedItem,
                true, // ismultiple
                isSelected, // forceselect
                false // triggerchangeevent
              );
            } else {
              // for single select, just reset to the default selected
              this.resetSelection();
            }
          }
        });
      });

      observer.observe(option, {
        attributes: true,
        attributeFilter: ['selected']
      });

      this.optionObservers.push(observer);
    });
  }

  disconnectMutationObservers() {
    if (this.optionObservers && this.optionObservers.length) {
      this.optionObservers.forEach(observer => observer.disconnect());
      this.optionObservers = [];
    }
  }
}
