import AirDatepicker from 'air-datepicker';
import localeZh from 'air-datepicker/locale/zh';
import { format, parse, isValid } from 'date-fns';

export default class DateInputService {
  datepicker;

  get datePickerVisible() {
    return this.datePicker?.visible ?? false;
  }

  /**  
   * cleanInput 是外面傳進來的 function，用來清空 input value
   * @param {Element} thisEle c-input本身
   * @param {ElementInternals} internals
   * @param {boolean} isDatetimePicker 是否日歷要包含時間讓使用者選擇
   * @param {boolean} isMonthPicker 是否日歷要變成僅能選擇年月的模式
   * @param {boolean} isYearPicker 是否日歷要變成僅能選擇年的模式
   */
  constructor(
      thisEle,
      input,
      internals,
      cleanInput,
      isDatetimePicker = false,
      isMonthPicker = false,
      isYearPicker = false,
      dateFormat) {

    this.thisEle = thisEle;
    this.input = input;
    this.isDatetimePicker = isDatetimePicker;
    this.isMonthPicker = isMonthPicker;
    this.isYearPicker = isYearPicker;
    this.dateFormat = this.#getDateFormat(dateFormat, isMonthPicker, isYearPicker);
    this.cleanInput = cleanInput;
    this.internals = internals;
    this.#initDatePicker(input, internals, isDatetimePicker, isMonthPicker, isYearPicker, dateFormat);

    this.valueBeforeChange = input.value || thisEle.getAttribute('value');
    this.valueAfterChange = null;
  }

  clearDatePicker() {
    this.datePicker.clear();
  }

  selectDate(dateStr) {
    this.#selectDate(this.datePicker, dateStr, this.isDatetimePicker, this.isMonthPicker, this.isYearPicker, this.dateFormat);
  }

  renewDatePickerPosition() {
    if (this.datePickerVisible) {
      this.datePicker.setPosition(this.datePicker.opts.position);
    }
  }

  #getDateFormat(dateFormat, isMonthPicker, isYearPicker) {
    if (isMonthPicker) {
      return 'yyyy/MM';
    }

    if (isYearPicker) {
      return 'yyyy';
    }

    if (dateFormat === 'yyyyMMdd') {
      return 'yyyyMMdd';
    } else if (dateFormat === 'yyyy/MM/dd') {
      return 'yyyy/MM/dd';
    } else {
      alert('only yyyy/MM/dd or yyyyMMdd is supported by now');
    }
  }

  #initDatePicker(input, internals, isDatetimePicker, isMonthPicker, isYearPicker, dateFormat) {
    const self = this;

    this.datePicker = new AirDatepicker(input, {
      locale: localeZh,
      autoClose: true,
      view: isYearPicker ? 'years' : isMonthPicker ? 'months' : 'days',
      minView: isYearPicker ? 'years' : isMonthPicker ? 'months' : 'days',
      dateFormat: (date) => format(date, dateFormat),
      timepicker: isDatetimePicker,
      navTitles: {
        days: 'yyyy/MM'
      },
      onShow: (isFinished) => {
        const isReadOnly = this.thisEle.hasAttribute('readonly') || this.input.hasAttribute('readonly');
        if (!isFinished && isReadOnly) {
          this.datePicker.hide();
        }
      },
      onSelect: ({ date, formattedDate, datepicker }) => {
        internals.setFormValue(input.value);
      },
      onHide: (isFinished) => {
        // clear input value if dateformat is invalid
        if (!isFinished) {
          if (input.value.length > 0 && !this.#isValidDateFormat(input.value, isDatetimePicker, isMonthPicker, isYearPicker, dateFormat)) {
            this.cleanInput();
          }
        } else {
          // 模擬input 觸發onchange事件
          self.valueAfterChange = self.input.value;
          if (self.valueBeforeChange !== self.valueAfterChange) {
            self.thisEle.dispatchEvent(new Event('change'));
          }
          self.valueBeforeChange = self.valueAfterChange;
        }
      },
    });
  }

  #isValidDateFormat(dateString, isDatetimePicker, isMonthPicker, isYearPicker, dateFormat) {
    if (isDatetimePicker === undefined) {
      alert('isDatetimePicker should be specified');
    }

    if (isMonthPicker === undefined) {
      alert('isMonthPicker should be specified');
    }

    if (isYearPicker === undefined) {
      alert('isYearPicker should be specified');
    }

    if (dateFormat === undefined) {
      alert('dateFormat should be specified');
    }


    let regex
    if (dateFormat == 'yyyy/MM/dd') {
      regex = isDatetimePicker
        ? /^\d{4}\/\d{2}\/\d{2} \d{2}:\d{2}$/ // yyyy/MM/dd HH:mm
        : /^\d{4}\/\d{2}\/\d{2}$/; // yyyy/MM/dd
    } else if (dateFormat == 'yyyyMMdd') {
      regex = /^\d{8}$/; // yyyyMMdd
    } else if (dateFormat == 'yyyy/MM' && isMonthPicker) {
      regex = /^\d{4}\/\d{2}$/; // yyyy/MM
    } else if (dateFormat == 'yyyy' && isYearPicker) {
      regex = /^\d{4}$/; // yyyy
    } else {
      alert('only yyyy/MM/dd or yyyyMMdd is supported by now');
    }

    const parsedDate = parse(dateString, dateFormat, new Date());

    return regex.test(dateString) && isValid(parsedDate);
  }

  // sync input value to datepicker
  // dateStr: yyyy/MM/dd or yyyy/MM/dd HH:mm or yyyyMMdd
  #selectDate(datePicker, dateStr, isDatetimePicker, isMonthPicker, isYearPicker, dateFormat) {
    if (dateStr && dateStr.length > 0 && this.#isValidDateFormat(dateStr, isDatetimePicker, isMonthPicker, isYearPicker, dateFormat)) {
      const parsedDate = parse(dateStr, dateFormat, new Date());
      datePicker.selectDate(parsedDate, { updateTime: isDatetimePicker });
      datePicker.setViewDate(parsedDate); // without this, datepicker sometimes not showing the selected date
    } else {
      datePicker.clear();
    }
  }
}
