export const templates = {
  select: `
    <span class="dropdown-icon" tabindex="-1">
      <!-- clear icon -->
      <!-- feathericons chevron-down 16px #248c92 -->
      <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#248c92" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="feather feather-chevron-down"><polyline points="6 9 12 15 18 9"></polyline></svg>  
    </span>
    <slot style="display: none">
      <!--  <option selected disabled hidden>select an option...</option>-->
      <!--  <option value="1">option1</option>-->
      <!--  <option value="2">option2</option>-->
    </slot>
  `,

  // 下拉選單展開的區塊
  dropdown: `
    <div class="search"><input type="text" placeholder="search"></div>
    <div class="scroll-overlay-y">
      <ul class="options scroll-body">
        <!--
          <li class="option" value="1"><span claass="icon-checkmark"></span>option1</li>
          <li class="option" value="2"><span claass="icon-checkmark"></span>option2</li>
        -->
        </ul>
    </div>
  `,

  dropdownItem: ({ value, label, selected }) => `
    <li class="option${selected ? ' selected' : ''}" value="${value}" id="option-${value}">
      <span class="icon-checkmark"></span>${label}</li>
  `,

  multiSelectTag: ({ label, value }) => `
    <span class="tag" data-value="${value}">
      ${label}<span class="icon-close">x</span>
    </span>
  `
};
