export function appendAsterisk(label) {
  const asterisk = document.createElement('span');
  asterisk.classList.add('asterisk');
  asterisk.textContent = '*';
  label.appendChild(asterisk);
}

export function appendPendingText(label) {
  const pendingText = document.createElement('div');
  pendingText.classList.add('pending-approval-text', 'text-rose-500', 'font-bold', 'text-2xs');
  pendingText.textContent = '(待放行)';
  label.appendChild(pendingText);
}
