.c-input {
  display: flex;
  align-items: center;
  min-height: 15px;
}
.c-input:hover .checkbox__box {
  border-color: #248c92;
}

:host(:focus-within:not([disabled]):not([readonly])) .radio__circle {
  border-color: hsl(183, 100%, 25%);
  box-shadow: 0 0 0 0.03rem #8fc4c7;
}

:host([readonly]) .radio__circle {
  border: 1px solid #a8d1d4;
}
:host([readonly]) .c-input__input:checked + .radio__circle .radio__inner-circle {
  opacity: 0.8;
}

.c-input__input {
  width: 20px;
  height: 15px;
  transform: translateX(1px) translateY(-1px);
  margin: 0px 0px 0px 0px;
  opacity: 0;
  position: absolute;
  cursor: pointer;
}
.c-input__input:checked + .radio__circle .radio__inner-circle {
  opacity: 1;
}
.c-input__input:checked ~ .radio__label {
  opacity: 1;
}
.c-input__input:checked + .radio__circle {
  border-color: #248c92;
}
.c-input__input:disabled ~ .radio__label {
  filter: contrast(70%);
}
.c-input__input:disabled + .radio__circle {
  border-width: 1px;
  border-color: var(--c-slate-400);
  box-shadow: none;
}
.c-input__input:disabled + .radio__circle .radio__inner-circle {
  filter: grayscale(100%) brightness(140%);
}

.radio__circle {
  background-color: white;
  position: absolute;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid #479fa4;
  margin: 3px 4px 0px 3px;
  margin-top: 0px;
  margin-right: 0px;
  margin-bottom: 0px;
  pointer-events: none;
  transition: background-color 200ms ease;
  display: grid;
  place-items: center;
}
.radio__circle .radio__inner-circle {
  width: 100%;
  height: 100%;
  background-image: radial-gradient(#248c92, #248c92 40%, transparent 60%);
  border-radius: 50%;
  opacity: 0;
  transition: transform 100ms ease, opacity 200ms ease;
}

.radio__label {
  font-size: 0.85rem;
  font-weight: 400;
  font-family: var(--c-font-family, var(--c-font-family-fallback));
  color: var(--c-slate-900);
  cursor: pointer;
  user-select: none;
