FA,eAAA;EACA,iBAAA;EACA,kBAAA;AAgWF","sourcesContent":["@use \"sass:map\";\r\n\r\n$primary-dark-1: hsl(183, 100%, 22%);\r\n$primary-dark-2: hsl(183, 100%, 20%);\r\n$primary-l1: hsl(183, 100%, 28%);\r\n$primary-light-2: hsl(183, 100%, 40%);\r\n$primary-light-4: hsl(183, 45%, 90%);\r\n$primary-light-5: hsl(192, 50%, 96%); // from sfap\r\n$primary-blueish: hsl(193, 96%, 31%);\r\n$sfap-header-bg: hsl(182, 98%, 25%);\r\n$sfap-table-bg: hsl(183, 100%, 25%); // 最深\r\n$sfap-tab-color: hsl(182, 59%, 36%);\r\n$sfap-bell-bg: hsl(180, 65%, 33%); // 小鈴鐺\r\n$sfap-btn-bg: hsl(171, 41%, 51%); // 感覺隨便選的，有點青蘋果綠\r\n\r\n$danger: hsl(359, 82%, 55%); // 從首頁來\r\n$danger-pinkish: hsl(337, 92%, 49%); // gradient\r\n\r\n$secondary: hsl(183, 91%, 17%);\r\n\r\n// use $c as the shorthand for csfds\r\n// $c: (\r\n//   ) $primary: hsl(183, 100%, 25%\r\n//   );\r\n$primary: hsl(183, 100%, 25%);\r\n$primary-50: mix(white, $primary-light-4, 70%);\r\n$primary-80: mix(white, $primary, 66%);\r\n$primary-100: mix(white, $primary, 56%);\r\n$primary-200: mix(white, $primary, 42%);\r\n$primary-300: mix(white, $primary, 28%);\r\n$primary-400: mix(white, $primary, 14%);\r\n$primary-500: $primary;\r\n$primary-600: mix(black, $primary, 12%);\r\n$primary-700: mix(black, $primary, 24%);\r\n$primary-800: mix(black, $primary, 36%);\r\n$primary-900: mix(black, $primary, 50%);\r\n\r\n$cyan: mix(rgb(61, 140, 210), $primary, 30%);\r\n$cyan-50: mix(white, #cbe8f0, 70%);\r\n$cyan-80: #cbe8f0;\r\n$cyan-100: mix(white, $cyan, 56%);\r\n$cyan-200: mix(white, $cyan, 42%);\r\n$cyan-300: mix(white, $cyan, 28%);\r\n$cyan-400: mix(white, $cyan, 14%);\r\n$cyan-500: $cyan;\r\n$cyan-600: mix(black, $cyan, 12%);\r\n$cyan-700: mix(black, $cyan, 24%);\r\n$cyan-800: mix(black, $cyan, 36%);\r\n$cyan-900: mix(black, $cyan, 50%);\r\n\r\n// borrowed from tailwindcss\r\n$c: (\r\n  primary: (\r\n    50: $primary-50,\r\n    80: $primary-light-4,\r\n    100: $primary-100,\r\n    200: $primary-200,\r\n    300: $primary-300,\r\n    400: $primary-400,\r\n    500: $primary,\r\n    600: $primary-600,\r\n    700: $primary-700,\r\n    800: $primary-800,\r\n    900: $primary-900,\r\n  ),\r\n  \"cyan\": (\r\n    50: $cyan-50,\r\n    80: $cyan-80,\r\n    100: $cyan-100,\r\n    200: $cyan-200,\r\n    300: $cyan-300,\r\n    400: $cyan-400,\r\n    500: $cyan,\r\n    600: $cyan-600,\r\n    700: $cyan-700,\r\n    800: $cyan-800,\r\n    900: $cyan-900,\r\n  ),\r\n  slate: (\r\n    50: #f8fafc,\r\n    100: #f1f5f9,\r\n    200: #e2e8f0,\r\n    300: #cbd5e1,\r\n    350: #afbdd0,\r\n    400: #94a3b8,\r\n    500: #64748b,\r\n    600: #475569,\r\n    700: #334155,\r\n    800: #1e293b,\r\n    900: #0f172a,\r\n  ),\r\n  rose: (\r\n    50: #fff1f2,\r\n    100: #ffe4e6,\r\n    200: #fecdd3,\r\n    300: #fda4af,\r\n    400: #fb7185,\r\n    500: #f43f5e,\r\n    600: #e11d48,\r\n    700: #be123c,\r\n    800: #9f1239,\r\n    900: #4c0519,\r\n  )\r\n);\r\n\r\n// generate --c-slate-100, --c-slate-200... css properties\r\n:root {\r\n  --c-danger: hsl(359, 82%, 55%);\r\n  --c-blue-1: rgb(55, 150, 190);\r\n\r\n  @each $colorname, $palette in $c {\r\n    @each $key, $value in $palette {\r\n      // --c is the prefix for csfds variables\r\n      $keyname: \"--c-\" + $colorname + \"-\" + $key;\r\n      #{$keyname}: #{$value};\r\n    }\r\n  }\r\n}\r\n\r\n// generate .bg-slate-100, .bg-slate-200... css classes\r\n.bg {\r\n  @each $colorname, $palette in $c {\r\n    @each $key, $value in $palette {\r\n\r\n      // --c is the prefix for csfds variables\r\n      &-#{$colorname}-#{$key} {\r\n        background-color: var(--c-#{$colorname}-#{$key});\r\n\r\n        @if $colorname ==primary and $key >=400 {\r\n          color: white;\r\n        }\r\n\r\n        @else if $colorname ==\"cyan\" and $key >=500 {\r\n          color: white;\r\n        }\r\n\r\n        @else if $colorname ==slate and $key >=500 {\r\n          color: white;\r\n        }\r\n\r\n        @else if $colorname ==rose and $key >=600 {\r\n          color: white;\r\n        }\r\n\r\n        @else {\r\n          color: black;\r\n        }\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n// generate .text-cyan-100, .text-rose-200... css classes\r\n.text {\r\n  @each $colorname, $palette in $c {\r\n    @each $key, $value in $palette {\r\n      // if $colorname == \"slate\", skip (專案初期有專門的.text-slate-xxx了，就仍先以那邊為主)\r\n      @if $colorname == \"slate\" {\r\n        @continue;\r\n      }\r\n\r\n      // --c is the prefix for csfds variables\r\n      &-#{$colorname}-#{$key} {\r\n        color: var(--c-#{$colorname}-#{$key});\r\n      }\r\n    }\r\n  }\r\n}\r\n","@use '../../scss/colors' as colors;\r\n@use '../../scss/input' as input;\r\n\r\n.c-input {\r\n  display: flex;\r\n  align-items: center;\r\n  min-height: 15px;\r\n\r\n  &:hover {\r\n    .checkbox__box {\r\n      @include input.input-hover-border;\r\n    }\r\n  }\r\n\r\n  // transform: translateY(-1px);\r\n}\r\n\r\n// 非disabled, readonly時的focus樣式\r\n:host(:focus-within:not([disabled]):not([readonly])) {\r\n  .radio__circle {\r\n    @include input.radio-focus-border-outline-light2;\r\n  }\r\n}\r\n\r\n// readonly時的樣式\r\n:host([readonly]) {\r\n  .radio__circle {\r\n    @include input.input-readonly-border-radio\r\n  }\r\n\r\n  .c-input__input:checked+.radio__circle .radio__inner-circle {\r\n    opacity: .8;\r\n  }\r\n}\r\n\r\n.c-input__input {\r\n  width: 20px;\r\n  height: 15px;\r\n  transform: translateX(1px) translateY(-1px);\r\n  margin: 0px 0px 0px 0px;\r\n\r\n  opacity: 0; // hide the native checkbox\r\n  position: absolute; // without pushing the radio-dot\r\n  cursor: pointer;\r\n\r\n  &:checked+.radio__circle .radio__inner-circle {\r\n    opacity: 1;\r\n  }\r\n\r\n  &:checked~.radio__label {\r\n    // font-weight: 700;\r\n    opacity: 1;\r\n  }\r\n\r\n  &:checked+.radio__circle {\r\n    @include input.radio-focus-border-outline-light;\r\n  }\r\n\r\n  &:disabled~.radio__label {\r\n    @include input.disabled-text;\r\n  }\r\n\r\n  &:disabled+.radio__circle {\r\n    @include input.input-disabled-border;\r\n    box-shadow: none;\r\n  }\r\n\r\n  &:disabled+.radio__circle .radio__inner-circle {\r\n    filter: grayscale(100%) brightness(140%);\r\n  }\r\n}\r\n\r\n.radio__circle {\r\n  background-color: white;\r\n  position: absolute;\r\n\r\n  width: 12px;\r\n  height: 12px;\r\n  border-radius: 50%;\r\n  border: 2px solid colors.$primary-300;\r\n  margin: 3px 4px 0px 3px; // default browser radio's margin\r\n  margin-top: 0px;\r\n  margin-right: 0px;\r\n  margin-bottom: 0px; // push border bottom down to align with other inputs\r\n\r\n  pointer-events: none;\r\n  transition: background-color 200ms ease;\r\n\r\n  display: grid;\r\n  place-items: center;\r\n\r\n  .radio__inner-circle {\r\n    width: 100%;\r\n    height: 100%;\r\n    background-image: radial-gradient(colors.$primary-400, colors.$primary-400 40%, transparent 60%);\r\n    border-radius: 50%;\r\n\r\n    opacity: 0;\r\n    transition: transform 100ms ease, opacity 200ms ease;\r\n  }\r\n}\r\n\r\n.radio__label {\r\n  @include input.input-text;\r\n  cursor: pointer;\r\n  user-select: none;\r\n  padding-left: 20px;\r\n}\r\n",":root {\r\n    --c-font-family-fallback: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Microsoft JhengHei\", Roboto, Oxygen,\r\n        Ubuntu, Cantarell, \"Open Sans\", \"Helvetica Neue\", sans-serif;\r\n    --c-table-box-shadow-fallback: \r\n        rgba(0, 0, 0, 0.2) 0px 2px 1px -1px, \r\n        rgba(0, 0, 0, 0.14) 0px 1px 2px 1px, \r\n        rgba(0, 0, 0, 0.12) 0px 1px 3px 0px, \r\n        rgba(0, 0, 0, 0.08) 0px 1px 4px 0px;\r\n}\r\n\r\n\r\n$font-family-a: var(--c-font-family, var(--c-font-family-fallback));","@use \"sass:meta\";\r\n@use 'variables' as variables;\r\n@use 'colors' as colors;\r\n\r\n@mixin disabled-text {\r\n  filter: contrast(70%);\r\n}\r\n\r\n@mixin input-text-semi-bold {\r\n  font-size: .85rem;\r\n  font-weight: 500;\r\n  font-family: #{meta.inspect(variables.$font-family-a)};\r\n  color: var(--c-slate-900);\r\n}\r\n\r\n@mixin input-text {\r\n  font-size: .85rem;\r\n  font-weight: 400;\r\n  font-family: #{meta.inspect(variables.$font-family-a)};\r\n  color: var(--c-slate-900);\r\n}\r\n\r\n@mixin input-border {\r\n  border: 2px solid colors.$primary-200;\r\n  border-radius: 5px;\r\n}\r\n\r\n@mixin input-border-xs {\r\n  border: 1px solid colors.$primary-200;\r\n  border-radius: 3px;\r\n}\r\n\r\n@mixin input-readonly-border {\r\n  border: 1px solid colors.$primary-80;\r\n  border-radius: 5px;\r\n}\r\n\r\n@mixin input-readonly-border-checkbox {\r\n  border: 1px solid colors.$primary-80;\r\n}\r\n\r\n@mixin input-readonly-border-radio {\r\n  border: 1px solid colors.$primary-80;\r\n}\r\n\r\n@mixin input-disabled-border {\r\n  border-width: 1px;\r\n  border-color: var(--c-slate-400);\r\n}\r\n\r\n@mixin input-focus-border-outline {\r\n  border-color: colors.$primary-500;\r\n  box-shadow: 0 0 0 0.15rem colors.$primary-100;\r\n}\r\n\r\n@mixin input-focus-border-outline-xs {\r\n  border-color: colors.$primary-500;\r\n}\r\n\r\n@mixin input-focus-border-outline-light {\r\n  border-color: colors.$primary-500;\r\n  box-shadow: 0 0 0 0.09rem colors.$primary-100;\r\n}\r\n\r\n@mixin input-focus-border-outline-disabled {\r\n  border-color: var(--c-slate-400);\r\n  //box-shadow: 0 0 0 0.09rem var(--c-slate-300);\r\n  box-shadow: none;\r\n}\r\n\r\n@mixin input-focus-border-outline-disabled-xs {\r\n  border-color: var(--c-slate-700);\r\n  //box-shadow: 0 0 0 0.02rem var(--c-slate-300);\r\n  box-shadow: none;\r\n}\r\n\r\n@mixin radio-focus-border-outline-light {\r\n  border-color: colors.$primary-400;\r\n}\r\n\r\n@mixin radio-focus-border-outline-light2 {\r\n  border-color: colors.$primary-500;\r\n  box-shadow: 0 0 0 0.03rem colors.$primary-100;\r\n}\r\n\r\n@mixin input-hover-border {\r\n  border-color: colors.$primary-400;\r\n}\r\n"],"sourceRoot":""}]);
