import htmlStr from './CsfdsActionBar.html';
import cssStr from './CsfdsActionBar.scss';
import { moveToSlot, appendCssToHead } from "../../utils/web-comp-utils";
import CsfdsActionBarService from "./CsfdsActionBarService";

export default class CsfdsActionBar extends HTMLElement {
  #actionBarSvc;
  #defaultBtns = [];

  static define() {
    customElements.define('c-action-bar', CsfdsActionBar);
  }
  constructor() {
    super();
    this.#actionBarSvc = new CsfdsActionBarService();
    this.#defaultBtns = this
      .trimAll(this.getAttribute('defaultBtns'))
      .split(',');
  }

  get hasRendered() {
    return this.getAttribute('rendered');
  }

  set hasRendered(val) {
    this.setAttribute('rendered', val);
  }

  connectedCallback() {
    if (!this.hasRendered) {
      let template = this.initBtns(htmlStr);
      template = moveToSlot(template, this);
      template = this.processSlottedBtns(template);
      this.removeEmptySeparators(template);
      this.innerHTML = template.innerHTML;
      appendCssToHead(cssStr, 'csfds-action-bar-style');

      this.querySelector('.btn-reload')?.addEventListener(
        'click', () => {
          this.#reloadPage();
        });
      this.querySelector('.btn-back')?.addEventListener(
        'click', () => history.back());
      this.querySelector('.btn-cancel')?.addEventListener(
        'click', (e) => {
          e.target.closest('form').reset();
          e.target.closest('form').querySelectorAll('c-input, c-select').forEach(input => {
            input.reset();
          });
        });

      this.hasRendered = true;
    }
  }

  initBtns(htmlTemplateStr) {
    let template = document.createElement('template');
    template.innerHTML = htmlTemplateStr;

    // remove unwanted buttons
    const btns = template.content.querySelectorAll('button');
    for (let i = 0; i < btns.length; i++) {
      const btn = btns[i];
      if (!this.#defaultBtns.includes(btn.getAttribute('class'))) {
        btn.remove();
      }
    }

    return template;
  }

  /*
    * trim all white spaces, tabs, new lines
   */
  trimAll(strs) {
    strs = strs || '';
    return strs.replace(/\s+/g, '');
  }

  /**
   * 美化用，移除第一個和最後一個分隔線
   */
  removeEmptySeparators(template) {
    // if c-action-bar's first/last child is div.separator, remove it
    const firstChild = template.content.querySelector('.action-bar').firstElementChild;
    if (firstChild.tagName === 'DIV' && firstChild.classList.contains('separator')) {
      firstChild.remove();
    }
    const lastChild = template.content.querySelector('.action-bar').lastElementChild;
    if (lastChild.tagName === 'SLOT') {
      lastChild.previousElementSibling.remove();
      lastChild.remove();
    }
  }

  /**
   * 補齊支援按鈕的 svg icon 和 data-tooltip
   */
  processSlottedBtns(template) {
    // add svg icons to supported buttons
    const btnNew = template.content.querySelector('.btn-new');
    const btnSave = template.content.querySelector('.btn-save');
    const btnCancel = template.content.querySelector('.btn-cancel');
    const btnDelete = template.content.querySelector('.btn-delete');
    const btnExports = template.content.querySelectorAll('.btn-export');
    const btnReqApprv = template.content.querySelector('.btn-req-apprv');
    const btnCancelApprv = template.content.querySelector('.btn-cancel-apprv');
    const btnApprv = template.content.querySelectorAll('.btn-apprv');
    const btnReject = template.content.querySelectorAll('.btn-reject');
    const btnUpload = template.content.querySelector('.btn-upload');
    const btnModify = template.content.querySelector('.btn-modify');
    const btnWithdraw = template.content.querySelector('.btn-withdraw');
    const btnSend = template.content.querySelector('.btn-send');
    this.#actionBarSvc.prependSvgToButton(btnNew, 'file');
    this.#actionBarSvc.prependSvgToButton(btnSave, 'save');
    this.#actionBarSvc.prependSvgToButton(btnCancel, 'x-square');
    this.#actionBarSvc.prependSvgToButton(btnDelete, 'trash-2');
    this.#actionBarSvc.prependSvgToButtons(btnExports, 'download');
    this.#actionBarSvc.prependSvgToButton(btnReqApprv, 'hand-raised');
    this.#actionBarSvc.prependSvgToButton(btnCancelApprv, 'x-square');
    this.#actionBarSvc.prependSvgToButtons(btnApprv, 'smile');
    this.#actionBarSvc.prependSvgToButtons(btnReject, 'frown');
    this.#actionBarSvc.prependSvgToButton(btnUpload, 'upload');
    this.#actionBarSvc.prependSvgToButton(btnModify, 'modify');
    this.#actionBarSvc.prependSvgToButton(btnWithdraw, 'corner-up-left');
    this.#actionBarSvc.prependSvgToButton(btnSend, 'envelope');

    // add default data-tooltip to supported buttons
    this.#actionBarSvc.setDataTooltip(btnNew, '開新空白表單');
    this.#actionBarSvc.setDataTooltip(btnSave, '儲存');
    this.#actionBarSvc.setDataTooltip(btnCancel, '取消此次修改');
    this.#actionBarSvc.setDataTooltip(btnDelete, '刪除');
    this.#actionBarSvc.setDataTooltips(btnExports, '匯出Excel');
    this.#actionBarSvc.setDataTooltip(btnUpload, '檔案匯入');
    this.#actionBarSvc.setDataTooltip(btnModify, '修改');

    return template;
  }

  #reloadPage() {
    top.showLoader && top.showLoader();
    location.reload();
  }
}
