export class FormService {
  constructor(component) {
    this.component = component;
  }

  setFormValue(value) {
    // set the form value to be submitted with the form
    this.component.internals_.setFormValue(value);
  }

  setMultipleFormValues(values) {
    const name = this.component.getAttribute('name');

    if (!name || !values || values.length === 0) {
      this.component.internals_.setFormValue(null);
      return;
    }

    // for multiple values, use form data to allow multiple values with same name
    const formData = new FormData();
    values.forEach(value => {
      formData.append(name, value);
    });

    this.component.internals_.setFormValue(formData);
  }
}
