import './scss/row-draggable.scss';

/**
 * new RowDraggable(tableElement)
 * 讓table的body row可拖曳
 */
export default class RowDraggable {
  /**
   * @param tableElement {HTMLElement}
   */
  constructor(tableElement, options = {}) {
    this.tableElement = tableElement;

    this.bodyTrs = this.tableElement.querySelectorAll('tbody tr');
    // the row that is being dragged
    this.draggingTr = null;

    // after dragstart, recording how much the mouse has moved
    this.dragOffsetX = 0;
    this.dragOffsetY = 0;
    // intial position of the drag start mouse position
    this.dragStartX = 0;
    this.dragStartY = 0;

    // e.g., { columnsDraggable: [1, 2, 3] }
    //    or { columnsDraggable: 5 }
    // "columnsDraggable" start from 0
    //    if set, then only the specified columns can trigger the row dragging
    this.options = options;

    this.init();
  }

  init() {
    this.bodyTrs.forEach(tr => {
      this.#initDraggingTr(tr);
    });

    // also binding to newly created trs
    const observer = new MutationObserver(mutations => {
      mutations.forEach(mutation => {
        mutation.addedNodes.forEach(node => {
          if (node.tagName === 'TR' && !node.draggable) {
            this.#initDraggingTr(node);
          }
        });
      });
    });
    const tbody = this.tableElement.querySelector('tbody');
    observer.observe(tbody, { childList: true });
  }

  onDragStart(e) {
    const tr = e.target.closest('tr');
    // 當前一次drag drop的後處理還沒完成時，不允許再次drag
    if (tr.classList.contains('reordering')) {
      e.preventDefault();
      return;
    }
    this.draggingTr = tr;
    this.dragStartX = e.clientX;
    this.dragStartY = e.clientY;
  }

  onDrag(e) {
    this.dragOffsetX = e.clientX - this.dragStartX;
    this.dragOffsetY = e.clientY - this.dragStartY;
  }

  onDragOver(e) {
    e.preventDefault();
    const currentTr = e.target.closest('tr');

    if (this.draggingTr === currentTr) {
      return;
    }

    if (this.aboveHorizontalCenter(this.draggingTr, currentTr, this.dragOffsetY)) {
      currentTr.classList.remove('bottom-border');
      currentTr.classList.add('top-border');
    } else {
      currentTr.classList.remove('top-border');
      currentTr.classList.add('bottom-border');
    }
  }

  onDragLeave(e) {
    const currentTr = e.target.closest('tr');
    this.clearDragBorder(currentTr);
  }

  onDragDrop(e) {
    e.preventDefault();
    const currentTr = e.target.closest('tr');
    this.clearDragBorder(currentTr);

    if (this.draggingTr !== currentTr) {
      if (this.aboveHorizontalCenter(this.draggingTr, currentTr, this.dragOffsetY)) {
        currentTr.before(this.draggingTr);
      } else {
        currentTr.after(this.draggingTr);
      }
    }
  }

  /**
   * 檢查draggingTr是否在currentTr的水平中心以上
   */
  aboveHorizontalCenter(draggingTr, currentTr, dragOffsetY) {
    const draggingTrCenterY = draggingTr.getBoundingClientRect().top + dragOffsetY + draggingTr.getBoundingClientRect().height / 2;
    const currentTrCenterY = currentTr.getBoundingClientRect().top + currentTr.getBoundingClientRect().height / 2;
    const aboveHorizontalCenter = draggingTrCenterY < currentTrCenterY;
    return aboveHorizontalCenter;
  }

  clearDragBorder(currentTr) {
    currentTr.classList.remove('top-border');
    currentTr.classList.remove('bottom-border');
  }

  #initDraggingTr(tr) {
    console.log('initDraggingTr');
    tr.draggable = true;
    if (this.options.columnsDraggable) {
      const columnsDraggableIdx = [...this.options.columnsDraggable];
      const tds = tr.querySelectorAll('td');
      tds.forEach((td, i) => {
        if (!columnsDraggableIdx.includes(i)) {
          td.classList.add("c-undraggable");
        }
      });
    }
    tr.classList.add("c-draggable");
    tr.addEventListener('dragstart', this.onDragStart.bind(this));
    tr.addEventListener('drag', this.onDrag.bind(this));
    tr.addEventListener('dragover', this.onDragOver.bind(this));
    tr.addEventListener('dragleave', this.onDragLeave.bind(this));
    tr.addEventListener('drop', this.onDragDrop.bind(this));
  }
}
