import {hasSiblingOfSameType} from "../../utils/utils";

export default class CheckBoxRadioButtonService {

  constructor(component) {
    this.component = component;
  }

  /**
   * @param type 'checkbox' or 'radio'
   */
  renderCheckboxRadio(type, cInput) {
    if (hasSiblingOfSameType(cInput, type) && !cInput.hasAttribute('label')) {
      console.error(`label attribute is required for ${type} input`);
    }

    const label = cInput.getAttribute('label');
    const cssSelector = type === 'checkbox' ? '.checkbox__label' : '.radio__label';
    const labelEl = cInput.shadowRoot.querySelector(cssSelector);
    labelEl.innerHTML = label;

    labelEl.addEventListener('click', (e) => {
      // prevent click event on label to trigger input's click event
      e.stopPropagation();
    });

    // 如果有readonly屬性，則不能點選
    cInput.addEventListener('click', (e) => {
      if (cInput.hasAttribute('readonly')) {
        e.preventDefault();
        e.stopPropagation();
        return false;
      }
    })
  }

  clearRadioGroup() {
    const name = this.component.getAttribute('name');
    window.document.querySelectorAll(`c-input[type=radio][name='${name}']`).forEach(radio => {
      if (radio.ele) {
        radio.ele.input.checked = false;
        radio.clearFormInternals();
      }
    });
  }
}
