import CsfdsInput from '../csfds-input/CsfdsInput';
import styles from './CsfdsSelect.scss'
import realDropdownStyles from './CsfdsSelectRealDropdown.scss';

import { templates } from './templates.js';
import { DomService } from './services/dom-service.js';
import { EventService } from './services/event-service.js';
import { StateService } from './services/state-service.js';
import { FormService } from './services/form-service.js';
import { generateUUID } from "../../utils/utils";

/**
 * Events:
 *  c-select-before-open: before the options dropdown is opened
 *  c-select-open: when the options dropdown is opened
 *  c-select-close: when the options dropdown is closed
 */
export default class CsfdsSelect extends CsfdsInput {
  static get observedAttributes() {
    return [...CsfdsInput.observedAttributes, 'multiple', 'searchable', 'disabled'];
  }

  constructor() {
    super();

    this.isSelect = true; // parent's isSelect flag

    // create unique ids
    this.uuid = generateUUID();
    this.dropdownId = `dropdown_${this.uuid}`;

    // initialize services
    this.domService = new DomService(this);
    this.stateService = new StateService(this);
    this.formService = new FormService(this);
    this.eventService = new EventService(this, {
      domService: this.domService,
      stateService: this.stateService,
      formService: this.formService
    });

    this.isFirstRender = true;
  }

  connectedCallback() {
    if (!this.isFirstRender) {
      return;
    }

    super.connectedCallback();

    // initialize the component
    this.initialize();

    // set up shadow dom
    this.setupShadowDOM();

    // initialize the dropdown items
    this.renderDropdownItems();

    // set up event listeners
    this.eventService.addEventListener(this.shadowRoot, 'slotchange', this.handleSlotChange.bind(this));
    this.eventService.setupEventListeners();

    // select the default items
    this.selectDefaultItems();

    // component is now initialized
    this.isFirstRender = false;
  }

  attributeChangedCallback(name, oldValue, newValue) {
    super.attributeChangedCallback(name, oldValue, newValue);

    if (this.isFirstRender || oldValue === newValue) {
      return;
    }

    switch (name) {
      case 'multiple':
        this.stateService.setMultiple(this.hasAttribute('multiple'));
        this.render();
        break;
      case 'searchable':
        this.stateService.setSearchable(this.hasAttribute('searchable'));
        this.render();
        break;
      case 'disabled':
        this.stateService.setDisabled(this.hasAttribute('disabled'));
        this.render();
        break;
      case 'readonly':
        this.stateService.setReadonly(this.hasAttribute('readonly'));
        this.render();
        break;
    }
  }

  initialize() {
    // initialize component state
    this.stateService.setMultiple(this.hasAttribute('multiple'));
    this.stateService.setSearchable(this.hasAttribute('searchable'));
    this.stateService.setDisabled(this.hasAttribute('disabled'));
    this.stateService.setReadonly(this.hasAttribute('readonly'));
  }

  setupShadowDOM() {
    // append the template to the component's shadow dom
    const template = document.createElement('template');
    template.innerHTML = templates.select;

    this.shadowRoot.querySelector('.c-input')
      .appendChild(template.content.cloneNode(true));

    // create and append the dropdown to the body
    this.domService.createDropdown(templates.dropdown);

    // apply styles
    this.domService.applyStyles(styles, realDropdownStyles);

    // set initial state
    const input = this.shadowRoot.querySelector('.c-input__input');
    input.setAttribute('readonly', true);
  }

  handleSlotChange() {
    if (this.isFirstRender) {
      return;
    }
    this.render();
  }

  render() {
    this.renderDropdownItems();
    this.selectDefaultItems();
    this.updateSelectedItems();
  }

  renderDropdownItems() {
    this.domService.renderDropdownItems();
    this.domService.updateDropdownPosition();
  }

  selectDefaultItems() {
    this.domService.selectDefaultItems();
  }

  updateSelectedItems() {
    this.domService.updateSelectedItems();
  }

  // public api methods
  reset(triggerChangeEvent = true) {
    this.domService.resetSelection();

    if (triggerChangeEvent) {
      this.dispatchEvent(new Event('change'));
    }
  }

  get dropdownOption() {
    return document.getElementById(this.dropdownId);
  }

  /**
   * @typedef {Object} SelectOption 選項物件
   * @property {string} label - 選項顯示的文字
   * @property {string} value - 選項的值
   * @property {boolean} selected - 是否選取
   */

  /**
   * 變更選項
   *
   * @param {SelectOption[]} options 要異動的選項清單
   * @example
   * changeOptions([
   *   { label: '選項1', value: '1', selected: false },
   *   { label: '選項2', value: '2', selected: true }
   *  ]);
   */
  changeOptions(options) {
    if (!Array.isArray(options)) {
      console.error('Options must be an array');
      return;
    }

    this.domService.setOptions(options);
    this.render();
  }

  // getters and setters
  get recentValue() {
    return this.stateService.getRecentValue();
  }

  get value() {
    return this.stateService.getValue();
  }

  set value(val) {
    const dropdownItems = this.domService.getDropdownItems();
    const selectedItem = [...dropdownItems].find(item => item.getAttribute('value') === String(val));
    if (selectedItem === undefined) {
      this.stateService.setSelectedIndex(-1);
      this.stateService.setValue('');
      this.stateService.clearValues();
    } else {
      this.stateService.setSelectedIndex([...dropdownItems].indexOf(selectedItem));
      this.stateService.setValue(val);
    }

    this.updateSelectedItems();
  }

  get values() {
    return this.stateService.getValues();
  }

  set values(values) {
    if (!Array.isArray(values)) {
      console.error('Values must be an array');
      return;
    }

    this.stateService.setValues(values);
    this.updateSelectedItems();
  }

  get name() {
    return this.getAttribute('name');
  }

  get selectedIndex() {
    return this.stateService.getSelectedIndex();
  }

  set selectedIndex(val) {
    // update the actual value based on the index
    const dropdownItems = this.domService.getDropdownItems();
    const selectedItem = dropdownItems[val];
    if (selectedItem === undefined) {
      this.stateService.setSelectedIndex(-1);
      this.stateService.setValue('');
      this.stateService.clearValues();
    } else {
      this.stateService.setSelectedIndex(val);
      this.stateService.setValue(selectedItem.getAttribute('value'));
    }

    this.updateSelectedItems();
  }

  get disabled() {
    return this.stateService.isDisabled();
  }

  set disabled(value) {
    this.stateService.setDisabled(value);
    if (value) {
      this.setAttribute('disabled', '');
    } else {
      this.removeAttribute('disabled');
    }
  }

  get readOnly() {
    return this.stateService.isReadonly();
  }

  set readOnly(value) {
    this.stateService.setReadonly(value);
    if (value) {
      this.setAttribute('readonly', '');
    } else {
      this.removeAttribute('readonly');
    }
  }

  get options() {
    return this.domService.getOptionsFromSlot();
  }
}
