import htmlStr from './CsfdsSvg.html';
import cssStr from './CsfdsSvg.scss';

export default class CsfdsSvg extends HTMLElement {
  #htmlStr;
  #svgName;
  #svgWidth;
  #svgHeight;

  static define() {
    customElements.define('c-svg', CsfdsSvg);
  }

  constructor() {
    super();
    this.#htmlStr = htmlStr;
  }

  connectedCallback() {
    if (!this.shadowRoot) {
      this.attachShadow({mode: 'open'});

      this.#svgName = this.getAttribute('svgName');
      if (!this.#svgName) {
        alert('Attribute svgName is required for c-svg');
      }
      this.#svgWidth = this.getAttribute('svgWidth') || '18';
      this.#svgHeight = this.getAttribute('svgHeight') || '18';

      const template = document.createElement('template');
      template.innerHTML = this.#htmlStr;
      const htmlEle = template.content.cloneNode(true);
      const theSvg = htmlEle.querySelector(`[data-svg-name=${this.#svgName}]`);

      if (!theSvg) {
        alert(`No svg found with name: ${this.#svgName}`);
        return;
      }
      theSvg.setAttribute('width', this.#svgWidth);
      theSvg.setAttribute('height', this.#svgHeight);

      // init html
      this.shadowRoot.innerHTML = '';
      this.shadowRoot.appendChild(theSvg);

      // init css
      const style = new CSSStyleSheet();
      style.replaceSync(cssStr);
      this.shadowRoot.adoptedStyleSheets = [style];
    }
  }
}
