  height: 0.1rem;
  background-color: var(--c-blue-1);
  position: absolute;
  bottom: 2px;
  left: 0;
  transition: left 150ms ease, width 100ms ease, opacity 50ms ease 150ms;
}
c-tabs.sm .c-tabs button.tab {
  font-size: var(--c-h3-title-font-size);
  font-weight: bold;
}
c-tabs.sm .c-tabs .underline {
  background-color: var(--c-slate-300);
  bottom: 3.5px;
}
