  display: flex;
  width: 100%;
  max-width: 100%;
  overflow: auto;
  opacity: 0;
  flex-direction: column;
  font-size: var(--c-noraml-font-size);
  transition: opacity 150ms, visibility 0ms ease 150ms, height 150ms ease;
}
