// ctbc
import './ctbcpages/ctbc.js'
import './ctbcpages/ctbc.scss'

// main
import './scss/main.scss'
import OverlayScrollbar from './scss/overlay-scrollbar/OverlayScrollbar.js'
import RowDraggable from "./RowDraggable";
import CsfdsButton from './components/csfds-button/CsfdsButton'
import CsfdsSelect from './components/csfds-select/CsfdsSelect.js';
import CsfdsTableWrapper from './components/csfds-table/CsfdsTableWrapper';
import CsfdsLoader from './components/csfds-loader/CsfdsLoader.js';
import CsfdsInput from './components/csfds-input/CsfdsInput.js';
import CsfdsTableFooter from './components/csfds-table-footer/CsfdsTableFooter.js';
import CsfdsSidemenu from './components/csfds-sidemenu/CsfdsSidemenu.js';
import CsfdsSvg from "./components/csfds-svg/CsfdsSvg";
import CsfdsActionBar from "./components/csfds-action-bar/CsfdsActionBar";
import _CsfdsTab from "./components/csfds-tabs/_CsfdsTab";
import CsfdsTabs from "./components/csfds-tabs/CsfdsTabs";
import CsfdsModal from './components/csfds-modal/CsfdsModal.js';

// register custom elements
registerComponent('c-button', CsfdsButton);
registerComponent('c-input', CsfdsInput);
registerComponent('c-select', CsfdsSelect);
registerComponent('c-table-wrapper', CsfdsTableWrapper);
registerComponent('c-loader', CsfdsLoader);
registerComponent('c-svg', CsfdsSvg);
registerComponent('c-action-bar', CsfdsActionBar);
CsfdsTableFooter.define();
CsfdsSidemenu.define();
_CsfdsTab.define();
CsfdsTabs.define();
CsfdsModal.define();

function registerComponent(componentName, component) {
  if (!customElements.get(componentName)) {
    customElements.define(componentName, component);
  }
}

// scan document for .scroll-overlay-y elements
new OverlayScrollbar();

window.RowDraggable = RowDraggable;
